 * GC2145 Phase 0 — "camera id" command
 *
 * Reads the GC2145 chip ID registers (0xF0 → 0x21, 0xF1 → 0x45) via
 * open-drain SCCB bit-bang.  Does NOT implement video capture.
 *
 * Safety:  All board-level GPIO mappings are checked at runtime before
 * any hardware access.  If any required pin is unconfigured (-1), the
 * command prints the blocker list and returns -ENODEV without touching
 * any register.
 *
 * GPIO semantics (open-drain SCCB):
 *   Drive low  = configure as GPIO output, latch = 0
 *   Release    = configure as GPIO input (high-Z); external pull-up
 *                brings the line high.  Never actively drive high.
 *
 * Reference: GC2145 datasheet register map, ARMino Apache-2.0 source
 *            (bk_avdk_smp) for BK7258 GPIO register layout.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/arch.h>

#include "bk7258_gpio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Sentinel: GPIO pin not configured */

#define CAMERA_GPIO_UNCONFIGURED  (-1)

/* GC2145 chip ID values */

#define GC2145_REG_ID_H    0xf0
#define GC2145_REG_ID_L    0xf1
#define GC2145_ID_H        0x21
#define GC2145_ID_L        0x45

/* SCCB 7-bit slave address for GC2145 */

#define GC2145_SCCB_ADDR   0x3c

/* SCCB bit-bang timing.
 *
 * SCCB is electrically identical to I2C but has no clock-stretching.
 * A conservative 5 µs half-period gives ~100 kHz clock.
 * up_udelay(5) is used instead of busy-wait for portability.
 */

#define SCCB_HALF_PERIOD_US  5

/* Per-bit timeout: maximum iterations waiting for SCL/SDA to settle.
 * At 5 µs per check, 1000 iterations = 5 ms — far more than needed.
 */

#define SCCB_TIMEOUT_ITER    1000

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* Saved GPIO state for one pin: mux function, direction, output latch */

typedef struct
{
  uint32_t cfg;       /* BK7258_GPIO_CFG(pin) value */
  uint32_t func;      /* BK7258_SYS_GPIO_FUNC(pin) value */
  uintptr_t cfg_addr; /* register address */
  uintptr_t func_addr;
} gpio_state_t;

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Board-level GPIO configuration (from Kconfig).
 * Default = -1 (unconfigured); camera id refuses to proceed.
 */

static const int g_cam_sda_pin  = CONFIG_CAMERA_GPIO_SDA;
static const int g_cam_scl_pin  = CONFIG_CAMERA_GPIO_SCL;
static const int g_cam_rst_pin  = CONFIG_CAMERA_GPIO_RST;
static const int g_cam_pwr_pin  = CONFIG_CAMERA_GPIO_PWR_CTL;
static const int g_cam_pwdn_pin = CONFIG_CAMERA_GPIO_PWDNB;
static const int g_cam_mclk_pin = CONFIG_CAMERA_MCLK_GPIO;

/****************************************************************************
 * Private Functions — GPIO Helpers
 ****************************************************************************/

/****************************************************************************
 * Name: gpio_save_state
 *
 * Description:
 *   Save the current mux function, direction, output latch, and pull
 *   config for one GPIO pin.  Used to restore after temporary SCCB use.
 *
 ****************************************************************************/

static void gpio_save_state(int pin, gpio_state_t *s)
{
  s->cfg_addr  = BK7258_GPIO_CFG(pin);
  s->func_addr = BK7258_SYS_GPIO_FUNC(pin);
  s->cfg       = getreg32(s->cfg_addr);
  s->func      = getreg32(s->func_addr);
}

/****************************************************************************
 * Name: gpio_restore_state
 *
 * Description:
 *   Restore GPIO state saved by gpio_save_state().
 *
 *   Restore order (safety-first, avoids glitches):
 *     1. Set output latch to saved value (before enabling output)
 *     2. Restore full CFG (direction, pull, function)
 *     3. Restore mux function select
 *
 ****************************************************************************/

static void gpio_restore_state(const gpio_state_t *s)
{
  /* Step 1: set output latch to saved value before changing direction.
   * This prevents a momentaneous "drive wrong level" if the pin was
   * previously an input and we're restoring it as such.
   */

  putreg32(s->cfg, s->cfg_addr);

  /* Step 2: restore mux function select */

  putreg32(s->func, s->func_addr);
}

/****************************************************************************
 * Name: sccb_sda_low / sccb_sda_release / sccb_scl_low / sccb_scl_release
 *
 * Description:
 *   Open-drain GPIO control for SCCB bit-bang.
 *   "low"     = configure as GPIO output, latch = 0 (actively pull low)
 *   "release" = configure as GPIO input (high-Z); external pull-up
 *               brings the line high.  Never actively drive high.
 *
 ****************************************************************************/

static void sccb_sda_low(void)
{
  uint32_t cfg = getreg32(BK7258_GPIO_CFG(g_cam_sda_pin));

  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* GPIO mode */
  cfg &= ~GPIO_CFG_OUTPUT_EN;    /* enable output (active-low bit) */
  cfg &= ~GPIO_CFG_INPUT_EN;     /* disable input */
  cfg &= ~GPIO_CFG_OUTPUT;       /* latch = 0 */
  putreg32(cfg, BK7258_GPIO_CFG(g_cam_sda_pin));
}

static void sccb_sda_release(void)
{
  uint32_t cfg = getreg32(BK7258_GPIO_CFG(g_cam_sda_pin));

  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* GPIO mode */
  cfg |= GPIO_CFG_OUTPUT_EN;     /* disable output (active-low: 1=off) */
  cfg |= GPIO_CFG_INPUT_EN;      /* enable input (high-Z read) */
  putreg32(cfg, BK7258_GPIO_CFG(g_cam_sda_pin));
}

static void sccb_scl_low(void)
{
  uint32_t cfg = getreg32(BK7258_GPIO_CFG(g_cam_scl_pin));

  cfg &= ~GPIO_CFG_SECOND_FUNC;
  cfg &= ~GPIO_CFG_OUTPUT_EN;
  cfg &= ~GPIO_CFG_INPUT_EN;
  cfg &= ~GPIO_CFG_OUTPUT;
  putreg32(cfg, BK7258_GPIO_CFG(g_cam_scl_pin));
}

static void sccb_scl_release(void)
{
  uint32_t cfg = getreg32(BK7258_GPIO_CFG(g_cam_scl_pin));

  cfg &= ~GPIO_CFG_SECOND_FUNC;
  cfg |= GPIO_CFG_OUTPUT_EN;     /* disable output */
  cfg |= GPIO_CFG_INPUT_EN;      /* enable input */
  putreg32(cfg, BK7258_GPIO_CFG(g_cam_scl_pin));
}

/****************************************************************************
 * Name: sccb_sda_read
 *
 * Description:
 *   Read the current level of the SDA pin.  Pin must already be in
 *   input/high-Z mode.
 *
 ****************************************************************************/

static inline int sccb_sda_read(void)
{
  return (getreg32(BK7258_GPIO_CFG(g_cam_sda_pin)) & GPIO_CFG_INPUT)
         ? 1 : 0;
}

/****************************************************************************
 * Name: sccb_scl_wait_high
 *
 * Description:
 *   Wait for SCL to read high (released by all devices).
 *   Returns 0 on success, -ETIMEDOUT on timeout.
 *
 ****************************************************************************/

static int sccb_scl_wait_high(void)
{
  int i;

  for (i = 0; i < SCCB_TIMEOUT_ITER; i++)
    {
      if (getreg32(BK7258_GPIO_CFG(g_cam_scl_pin)) & GPIO_CFG_INPUT)
        {
          return 0;
        }

      up_udelay(1);
    }

  return -ETIMEDOUT;
}

/****************************************************************************
 * Name: sccb_init_bus / sccb_release_bus
 *
 * Description:
 *   Set SCL/SDA to input mode (released, pulled high by external
 *   resistors).  This is the idle state.
 *
 ****************************************************************************/

static void sccb_init_bus(void)
{
  sccb_sda_release();
  sccb_scl_release();
  up_udelay(SCCB_HALF_PERIOD_US);
}

/****************************************************************************
 * Name: sccb_start
 *
 * Description:
 *   Generate SCCB START condition: SDA falls while SCL is high.
 *
 ****************************************************************************/

static void sccb_start(void)
{
  sccb_sda_low();
  up_udelay(SCCB_HALF_PERIOD_US);
  sccb_scl_low();
  up_udelay(SCCB_HALF_PERIOD_US);
}

/****************************************************************************
 * Name: sccb_stop
 *
 * Description:
 *   Generate SCCB STOP condition: SDA rises while SCL is high.
 *
 ****************************************************************************/

static void sccb_stop(void)
{
  sccb_sda_low();
  up_udelay(SCCB_HALF_PERIOD_US);
  sccb_scl_release();
  up_udelay(SCCB_HALF_PERIOD_US);
  sccb_sda_release();
  up_udelay(SCCB_HALF_PERIOD_US);
}

/****************************************************************************
 * Name: sccb_write_byte
 *
 * Description:
 *   Write one byte on the SCCB bus.  Checks the ACK bit.
 *
 * Input:
 *   byte — 8-bit value to send
 *
 * Returns:
 *   0 if ACK received, -EIO if NACK.
 *
 ****************************************************************************/

static int sccb_write_byte(uint8_t byte)
{
  int bit;
  int ack;
  int ret;

  /* Shift out 8 bits, MSB first */

  for (bit = 7; bit >= 0; bit--)
    {
      if ((byte >> bit) & 1)
        {
          sccb_sda_release();
        }
      else
        {
          sccb_sda_low();
        }

      up_udelay(SCCB_HALF_PERIOD_US);

      /* Clock high — slave samples data */

      sccb_scl_release();
      ret = sccb_scl_wait_high();
      if (ret < 0)
        {
          return ret;
        }

      up_udelay(SCCB_HALF_PERIOD_US);

      /* Clock low for next bit */

      sccb_scl_low();
      up_udelay(SCCB_HALF_PERIOD_US);
    }

  /* ACK bit: release SDA, clock high, read ACK */

  sccb_sda_release();
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_release();
  ret = sccb_scl_wait_high();
  if (ret < 0)
    {
      return ret;
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  ack = sccb_sda_read();

  sccb_scl_low();
  up_udelay(SCCB_HALF_PERIOD_US);

  /* ACK = SDA low (0), NACK = SDA high (1) */

  return ack ? -EIO : 0;
}

/****************************************************************************
 * Name: sccb_read_byte
 *
 * Description:
 *   Read one byte from the SCCB bus.  Sends NACK after the last byte
 *   (as required by the SCCB protocol).
 *
 * Returns:
 *   The byte read (0–255) on success, or negative errno on error.
 *
 ****************************************************************************/

static int sccb_read_byte(void)
{
  uint8_t byte = 0;
  int bit;
  int ret;

  /* Release SDA for slave to drive */

  sccb_sda_release();
  up_udelay(SCCB_HALF_PERIOD_US);

  /* Read 8 bits, MSB first */

  for (bit = 7; bit >= 0; bit--)
    {
      sccb_scl_release();
      ret = sccb_scl_wait_high();
      if (ret < 0)
        {
          return ret;
        }

      up_udelay(SCCB_HALF_PERIOD_US);

      if (sccb_sda_read())
        {
          byte |= (1u << bit);
        }

      sccb_scl_low();
      up_udelay(SCCB_HALF_PERIOD_US);
    }

  /* Send NACK (hold SDA high) to signal last byte, then STOP */

  sccb_sda_release();
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_release();
  ret = sccb_scl_wait_high();
  if (ret < 0)
    {
      return ret;
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_low();
  up_udelay(SCCB_HALF_PERIOD_US);

  return (int)byte;
}

/****************************************************************************
 * Name: camera_check_board_config
 *
 * Description:
 *   Verify all required board-level GPIO mappings are configured.
 *   Returns 0 if all are set, or prints the blocker list and returns
 *   -ENODEV.
 *
 ****************************************************************************/

static int camera_check_board_config(void)
{
  bool ok = true;

  syslog(LOG_INFO,
         "[camera] board config check:\n"
         "  SCCB_SDA  = %d\n"
         "  SCCB_SCL  = %d\n"
         "  DVP_RST   = %d\n"
         "  PWR_CTL   = %d\n"
         "  PWDNB     = %d\n"
         "  MCLK      = %d\n",
         g_cam_sda_pin, g_cam_scl_pin, g_cam_rst_pin,
         g_cam_pwr_pin, g_cam_pwdn_pin, g_cam_mclk_pin);

  if (g_cam_sda_pin == CAMERA_GPIO_UNCONFIGURED)
    {
      syslog(LOG_ERR, "[camera] BLOCKER: SCCB SDA not configured\n");
      ok = false;
    }

  if (g_cam_scl_pin == CAMERA_GPIO_UNCONFIGURED)
    {
      syslog(LOG_ERR, "[camera] BLOCKER: SCCB SCL not configured\n");
      ok = false;
    }

  if (g_cam_rst_pin == CAMERA_GPIO_UNCONFIGURED)
    {
      syslog(LOG_ERR, "[camera] BLOCKER: DVP_RST not configured\n");
      ok = false;
    }

  /* Power control and PWDNB are optional for Phase 0.
   * If unconfigured, print a warning but do not block.
   * (Some boards may have power always-on.)
   */

  if (g_cam_pwr_pin == CAMERA_GPIO_UNCONFIGURED)
    {
      syslog(LOG_WARNING,
             "[camera] WARNING: PWR_CTL not configured "
             "(assuming power always-on)\n");
    }

  if (g_cam_pwdn_pin == CAMERA_GPIO_UNCONFIGURED)
    {
      syslog(LOG_WARNING,
             "[camera] WARNING: PWDNB not configured "
             "(assuming not in standby)\n");
    }

  /* MCLK is a blocker for now: without verified 24 MHz clock the
   * sensor will not respond.  This will be resolved once the ARMino
   * clock tree analysis confirms the register semantics.
   */

  if (g_cam_mclk_pin == CAMERA_GPIO_UNCONFIGURED)
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: MCLK GPIO not configured\n"
             "[camera]   GC2145 requires 24 MHz MCLK to respond.\n"
             "[camera]   Set CONFIG_CAMERA_MCLK_GPIO after verifying\n"
             "[camera]   the BK7258 DVP clock tree (sys_drv_set_auxs_cis).\n");
      ok = false;
    }

  if (!ok)
    {
      syslog(LOG_ERR,
             "[camera] Cannot proceed — fix blockers above first.\n"
             "[camera] No GPIOs were modified.\n");
      return -ENODEV;
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_camera_id
 *
 * Description:
 *   Phase 0 "camera id" command.  Reads GC2145 registers 0xF0 and 0xF1
 *   via open-drain SCCB bit-bang and prints the chip ID.
 *
 *   Safety: checks all board GPIO mappings first.  If any required pin
 *   is unconfigured, exits without touching any hardware register.
 *
 * Returns:
 *   0 on success (ID matches 0x2145), negative errno on failure.
 *
 ****************************************************************************/

int bk7258_camera_id(void)
{
  gpio_state_t sda_saved;
  gpio_state_t scl_saved;
  gpio_state_t rst_saved;
  gpio_state_t mclk_saved;
  int id_h = -1;
  int id_l = -1;
  uint16_t chip_id;
  int ret;
  bool bus_active = false;

  syslog(LOG_INFO,
         "[camera] === GC2145 chip ID read (Phase 0) ===\n");

  /* ---- Step 1: Check board configuration ---- */

  ret = camera_check_board_config();
  if (ret < 0)
    {
      return ret;
    }

  /* ---- Step 2: Save GPIO states for all pins we will modify ---- */

  syslog(LOG_INFO, "[camera] saving GPIO states...\n");

  gpio_save_state(g_cam_sda_pin, &sda_saved);
  gpio_save_state(g_cam_scl_pin, &scl_saved);
  gpio_save_state(g_cam_rst_pin, &rst_saved);

  if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      gpio_save_state(g_cam_mclk_pin, &mclk_saved);
    }

  /* ---- Step 3: Configure SCCB pins as GPIO open-drain ---- */

  syslog(LOG_INFO,
         "[camera] configuring SCCB pins (SDA=P%d, SCL=P%d)\n",
         g_cam_sda_pin, g_cam_scl_pin);

  sccb_init_bus();
  bus_active = true;

  /* ---- Step 4: Hardware reset ---- */

  syslog(LOG_INFO,
         "[camera] hardware reset (RST=P%d active-low)\n",
         g_cam_rst_pin);

  /* Configure RST pin as GPIO output, initially high (inactive) */

  {
    uint32_t cfg = getreg32(BK7258_GPIO_CFG(g_cam_rst_pin));

    cfg &= ~GPIO_CFG_SECOND_FUNC;
    cfg &= ~GPIO_CFG_OUTPUT_EN;
    cfg &= ~GPIO_CFG_INPUT_EN;
    cfg |= GPIO_CFG_OUTPUT;  /* high = inactive (active-low reset) */
    putreg32(cfg, BK7258_GPIO_CFG(g_cam_rst_pin));
  }

  up_mdelay(10);

  /* Assert reset (low) */

  {
    uint32_t cfg = getreg32(BK7258_GPIO_CFG(g_cam_rst_pin));

    cfg &= ~GPIO_CFG_OUTPUT;
    putreg32(cfg, BK7258_GPIO_CFG(g_cam_rst_pin));
  }

  up_mdelay(20);

  /* Deassert reset (high) */

  {
    uint32_t cfg = getreg32(BK7258_GPIO_CFG(g_cam_rst_pin));

    cfg |= GPIO_CFG_OUTPUT;
    putreg32(cfg, BK7258_GPIO_CFG(g_cam_rst_pin));
  }

  up_mdelay(50);

  /* ---- Step 5: MCLK configuration ---- */

  if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      /* MCLK configuration requires verified register semantics.
       *
       * TODO: Implement after confirming from ARMino source:
       *   - sys_drv_set_auxs_cis() register fields
       *   - Actual clock source frequency
       *   - Pre/post divider semantics (+1/-1)
       *   - Gate, mux, enable order
       *   - P27 function select value for DVP_MCLK
       *
       * For now, log that MCLK is needed but not yet configured.
       * The SCCB read below will likely NACK without MCLK.
       */

      syslog(LOG_WARNING,
             "[camera] MCLK: P%d configured but 24 MHz clock\n"
             "[camera]   generation is not yet implemented.\n"
             "[camera]   SCCB read will likely fail without MCLK.\n",
             g_cam_mclk_pin);
    }

  /* ---- Step 6: SCCB read of 0xF0 / 0xF1 ---- */

  syslog(LOG_INFO,
         "[camera] reading chip ID via SCCB (addr=0x%02x)...\n",
         GC2145_SCCB_ADDR);

  /* Read register 0xF0 (ID high byte) */

  id_h = sccb_read_reg(GC2145_SCCB_ADDR, GC2145_REG_ID_H);
  if (id_h < 0)
    {
      syslog(LOG_ERR,
             "[camera] FAIL: SCCB read 0xF0 error=%d\n", id_h);
      syslog(LOG_ERR,
             "[camera]   Possible causes:\n"
             "[camera]   - MCLK not running (sensor not responding)\n"
             "[camera]   - SDA/SCL pins swapped or wrong\n"
             "[camera]   - Sensor not powered / in standby\n"
             "[camera]   - Pull-up resistors missing\n");
      ret = id_h;
      goto cleanup;
    }

  /* Read register 0xF1 (ID low byte) */

  id_l = sccb_read_reg(GC2145_SCCB_ADDR, GC2145_REG_ID_L);
  if (id_l < 0)
    {
      syslog(LOG_ERR,
             "[camera] FAIL: SCCB read 0xF1 error=%d\n", id_l);
      ret = id_l;
      goto cleanup;
    }

  chip_id = ((uint16_t)id_h << 8) | (uint16_t)id_l;

  /* ---- Step 7: Report result ---- */

  if (id_h == GC2145_ID_H && id_l == GC2145_ID_L)
    {
      syslog(LOG_INFO,
             "[camera] SUCCESS: GC2145 ID = 0x%04x\n", chip_id);
      ret = 0;
    }
  else
    {
      syslog(LOG_ERR,
             "[camera] ID MISMATCH: read 0x%02x%02x, "
             "expected 0x%04x\n",
             id_h, id_l,
             (GC2145_ID_H << 8) | GC2145_ID_L);
      ret = -ENODEV;
    }

cleanup:

  /* ---- Unified cleanup: restore all GPIO states ---- */

  syslog(LOG_INFO, "[camera] cleanup: restoring GPIO states\n");

  if (bus_active)
    {
      /* Release bus before restoring pins */

      sccb_sda_release();
      sccb_scl_release();
      up_udelay(SCCB_HALF_PERIOD_US);
    }

  /* Restore GPIO states (order: CFG first, then FUNC mux) */

  gpio_restore_state(&sda_saved);
  gpio_restore_state(&scl_saved);
  gpio_restore_state(&rst_saved);

  if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      gpio_restore_state(&mclk_saved);
    }

  syslog(LOG_INFO, "[camera] done (ret=%d)\n", ret);
  return ret;
}

