/* ---- Step 5: MCLK configuration (24 MHz on P27) ---- */

if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED)
  {
    /* Configure BK7258 CIS AUXS clock: 480 MHz PLL / (19+1) = 24 MHz
     *
     * Sequence (from ARMino dvp_camera_mclk_enable):
     *   1. Set P27 function to CLK_AUXS_CIS (func=1)
     *   2. Configure clock source and divider
     *   3. Enable CIS AUXS clock
     */

    uint32_t reg_val;

    syslog(LOG_INFO,
           "[camera] MCLK: configuring P%d for 24 MHz CIS AUXS clock\n",
           g_cam_mclk_pin);

    /* Step 5a: Set P27 function select to CLK_AUXS_CIS (value 1).
     * Read-modify-write the 4-bit field at bits [12:15] in the
     * GPIO function register for pins 24-31.
     */

    if (g_cam_mclk_pin == 27)
      {
        reg_val = getreg32(CAMERA_GPIO_FUNC_REG);
        reg_val &= ~(CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
        reg_val |= (CAMERA_P27_FUNC_CIS_CLK << CAMERA_P27_FUNC_SHIFT);
        putreg32(reg_val, CAMERA_GPIO_FUNC_REG);
      }
    else
      {
        syslog(LOG_ERR,
               "[camera] MCLK: only P27 is supported for CIS AUXS "
               "clock (configured P%d)\n",
               g_cam_mclk_pin);
        ret = -EINVAL;
        goto cleanup;
      }

    /* Step 5b: Set clock source = 3 (480 MHz PLL) and divider = 19.
     * Register 0x0A @ SYS_BASE+0x28:
     *   bits [15:16] = cksel = 3
     *   bits [17:21] = ckdiv = 19
     * Write order: set both fields in one write.
     */

    reg_val = getreg32(CAMERA_CLK_DIV_REG);
    reg_val &= ~((0x3u << CAMERA_CKSEL_POS) |
                  (0x1fu << CAMERA_CKDIV_POS));
    reg_val |= (CAMERA_CKSEL_AUXS_CIS << CAMERA_CKSEL_POS);
    reg_val |= (CAMERA_CKDIV_24MHZ << CAMERA_CKDIV_POS);
    putreg32(reg_val, CAMERA_CLK_DIV_REG);

    /* Step 5c: Enable CIS AUXS clock.
     * Register 0x0D @ SYS_BASE+0x34, bit [9] = cis_auxs_cken.
     */

    reg_val = getreg32(CAMERA_CLK_EN_REG);
    reg_val |= CAMERA_CIS_AUXS_CKEN_BIT;
    putreg32(reg_val, CAMERA_CLK_EN_REG);

    /* Allow clock to stabilize */

    up_udelay(100);

    syslog(LOG_INFO,
           "[camera] MCLK: 24 MHz enabled "
           "(cksel=%u, ckdiv=%u, 480/(%u+1)=%u MHz)\n",
           CAMERA_CKSEL_AUXS_CIS, CAMERA_CKDIV_24MHZ,
           CAMERA_CKDIV_24MHZ,
           480u / (CAMERA_CKDIV_24MHZ + 1));
  }

