/****************************************************************************
 * Name: sccb_read_reg
 *
 * Description:
 *   Read one register from an SCCB slave device.
 *
 *   SCCB read protocol (2-phase):
 *     Phase 1 (write): [START] [addr+W] [reg_addr] [STOP]
 *     Phase 2 (read):  [START] [addr+R] [data] [NACK] [STOP]
 *
 *   Note: SCCB requires a STOP between the write and read phases
 *   (unlike I2C which uses repeated START).
 *
 * Input:
 *   addr — 7-bit slave address (e.g. 0x3C for GC2145)
 *   reg  — 8-bit register address
 *
 * Returns:
 *   Register value (0–255) on success, negative errno on failure.
 *
 ****************************************************************************/

static int sccb_read_reg(uint8_t addr, uint8_t reg)
{
  int ret;

  /* Phase 1: write register address */

  sccb_start();

  ret = sccb_write_byte((addr << 1) | 0);  /* addr + W */
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "[sccb] NACK on addr write (0x%02x)\n", addr);
      goto out_stop;
    }

  ret = sccb_write_byte(reg);
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "[sccb] NACK on reg write (0x%02x)\n", reg);
      goto out_stop;
    }

  sccb_stop();

  /* Phase 2: read data */

  sccb_start();

  ret = sccb_write_byte((addr << 1) | 1);  /* addr + R */
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "[sccb] NACK on addr read (0x%02x)\n", addr);
      goto out_stop;
    }

  ret = sccb_read_byte();  /* sends NACK + leaves bus in post-read state */

  /* Always issue STOP after read */

  sccb_stop();
  return ret;

out_stop:
  sccb_stop();
  return ret < 0 ? ret : -EIO;
}

