/****************************************************************************
 * GC2145 Phase 0 — "camera id" command
 *
 * Reads the GC2145 chip ID registers (0xF0 → 0x21, 0xF1 → 0x45) via
 * open-drain SCCB bit-bang.  Does NOT implement video capture.
 *
 * Safety:  Two-stage config validation before any MMIO access:
 *   Stage 1 — Check all "confirmed" bools from Kconfig.  If ANY are n,
 *             print the full blocker list and return -ENOTSUP without
 *             touching any hardware register.
 *   Stage 2 — Validate GPIO pin values (range, uniqueness, conflicts).
 *
 * GPIO semantics (open-drain SCCB):
 *   Drive low  = configure as GPIO output, latch = 0
 *   Release    = configure as GPIO input (high-Z); external pull-up
 *                brings the line high.  Never actively drive high.
 *
 * Reference: GC2145 datasheet register map, ARMino Apache-2.0 source
 *            (bk_avdk_smp) for BK7258 GPIO register layout.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/arch.h>

#include "bk7258_gpio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Sentinel: GPIO pin not configured */

#define CAMERA_GPIO_UNCONFIGURED  (-1)

/* Valid GPIO range for BK7258: P0–P47 */

#define CAMERA_GPIO_MIN           0
#define CAMERA_GPIO_MAX           47

/* GC2145 chip ID values */

#define GC2145_REG_ID_H    0xf0
#define GC2145_REG_ID_L    0xf1
#define GC2145_ID_H        0x21
#define GC2145_ID_L        0x45

/* SCCB 7-bit slave address for GC2145 */

#define GC2145_SCCB_ADDR   0x3c

/* BK7258 DVP MCLK configuration (traced from ARMino Apache-2.0 source)
 *
 * Reference files:
 *   ap/components/bk_dvp/src/dvp_common.c        — dvp_camera_mclk_enable()
 *   ap/middleware/soc/bk7258_ap/soc/sys_struct.h   — register bit fields
 *   ap/middleware/soc/bk7258_ap/soc/sys_reg.h      — field positions
 *   ap/middleware/soc/bk7258_ap/soc/gpio_map.h     — P27 function map
 *
 * Clock tree:
 *   Source: 480 MHz PLL (cksel=3 selects this source)
 *   Divider: ckdiv_auxs_cis, 5 bits, semantics = divide by (ckdiv + 1)
 *   Output: 480 / (ckdiv + 1) MHz
 *   For 24 MHz: ckdiv = 19  →  480 / (19+1) = 24.000 MHz
 *
 * Register layout (reg 0x0A @ SYS_BASE + 0x28):
 *   bits [15:16] = cksel_auxs_cis  (2 bits, value 3 = 480 MHz PLL)
 *   bits [17:21] = ckdiv_auxs_cis  (5 bits, value 19 for 24 MHz)
 *
 * Clock enable (reg 0x0D @ SYS_BASE + 0x34):
 *   bit  [9]     = cis_auxs_cken   (1 = enable)
 *
 * P27 function select (pins 24-31 @ SYS_BASE + 0xCC):
 *   bits [12:15] = function for pin 27
 *   Value 1 = GPIO_DEV_CLK_AUXS_CIS (from gpio_map.h line 55)
 *   Value 0 = GPIO_DEV_JPEG_MCLK
 *
 * License: Apache-2.0 (ARMino / Beken)
 *   No Linux GPL content.  Register addresses and field positions are
 *   hardware facts from the vendor HAL, not derived from GPL code.
 */

/* SYS register base (same as BK7258_SYS_BASE in bk7258_gpio.h) */

#define CAMERA_SYS_BASE           0x44010000u

/* Clock source/divider register (reg 0x0A) */

#define CAMERA_CLK_DIV_REG        (CAMERA_SYS_BASE + 0x28u)
#define CAMERA_CKSEL_AUXS_CIS     3u     /* 480 MHz PLL source */
#define CAMERA_CKDIV_24MHZ        19u    /* 480/(19+1) = 24 MHz */
#define CAMERA_CKSEL_POS          15u
#define CAMERA_CKSEL_MASK         0x3u
#define CAMERA_CKDIV_POS          17u
#define CAMERA_CKDIV_MASK         0x1fu

/* Clock enable register (reg 0x0D) */

#define CAMERA_CLK_EN_REG         (CAMERA_SYS_BASE + 0x34u)
#define CAMERA_CIS_AUXS_CKEN_BIT  (1u << 9)

/* P27 function select register (pins 24-31) */

#define CAMERA_GPIO_FUNC_REG      (CAMERA_SYS_BASE + 0xCCu)
#define CAMERA_P27_FUNC_SHIFT     12u    /* (27%8)*4 = 3*4 = 12 */
#define CAMERA_P27_FUNC_MASK      0xFu
#define CAMERA_P27_FUNC_CIS_CLK   1u     /* GPIO_DEV_CLK_AUXS_CIS */

/* SCCB bit-bang timing.
 *
 * SCCB is electrically identical to I2C but has no clock-stretching.
 * A conservative 5 µs half-period gives ~100 kHz clock.
 * up_udelay(5) is used instead of busy-wait for portability.
 */

#define SCCB_HALF_PERIOD_US  5

/* Per-bit timeout: maximum iterations waiting for SCL/SDA to settle.
 * At 5 µs per check, 1000 iterations = 5 ms — far more than needed.
 */

#define SCCB_TIMEOUT_ITER    1000

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* Saved GPIO state for one pin: mux function, direction, output latch */

typedef struct
{
  uint32_t cfg;       /* BK7258_GPIO_CFG(pin) value */
  uint32_t func;      /* BK7258_SYS_GPIO_FUNC(pin) value */
  uintptr_t cfg_addr; /* register address */
  uintptr_t func_addr;
} gpio_state_t;

/* Saved MCLK register state (for proper restore on cleanup) */

typedef struct
{
  uint32_t clk_div;   /* reg 0x0A: source + divider */
  uint32_t clk_en;    /* reg 0x0D: clock gate */
  uint32_t func2431;  /* SYS_BASE+0xCC: P24-P31 function select */
  bool     valid;     /* true if state was saved */
} mclk_state_t;

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Board-level GPIO configuration (from Kconfig).
 * Default = -1 (unconfigured); camera id refuses to proceed.
 */

static const int g_cam_sda_pin  = CONFIG_CAMERA_GPIO_SDA;
static const int g_cam_scl_pin  = CONFIG_CAMERA_GPIO_SCL;
static const int g_cam_rst_pin  = CONFIG_CAMERA_GPIO_RST;
static const int g_cam_pwr_pin  = CONFIG_CAMERA_GPIO_PWR_CTL;
static const int g_cam_pwdn_pin = CONFIG_CAMERA_GPIO_PWDNB;
static const int g_cam_mclk_pin = CONFIG_CAMERA_MCLK_GPIO;

/****************************************************************************
 * Private Functions — GPIO Helpers
 ****************************************************************************/

/****************************************************************************
 * Name: gpio_is_valid
 *
 * Description:
 *   Check if a GPIO pin number is in the valid BK7258 range (0-47).
 *   CAMERA_GPIO_UNCONFIGURED (-1) is NOT valid — it means "not set".
 *
 ****************************************************************************/

static inline bool gpio_is_valid(int pin)
{
  return pin >= CAMERA_GPIO_MIN && pin <= CAMERA_GPIO_MAX;
}

/****************************************************************************
 * Name: gpio_save_state
 *
 * Description:
 *   Save the current mux function, direction, output latch, and pull
 *   config for one GPIO pin.  Used to restore after temporary SCCB use.
 *
 ****************************************************************************/

static void gpio_save_state(int pin, gpio_state_t *s)
{
  s->cfg_addr  = BK7258_GPIO_CFG(pin);
  s->func_addr = BK7258_SYS_GPIO_FUNC(pin);
  s->cfg       = getreg32(s->cfg_addr);
  s->func      = getreg32(s->func_addr);
}

/****************************************************************************
 * Name: gpio_restore_state
 *
 * Description:
 *   Restore a previously saved GPIO state.
 *
 ****************************************************************************/

static void gpio_restore_state(const gpio_state_t *s)
{
  putreg32(s->cfg, s->cfg_addr);
  putreg32(s->func, s->func_addr);
}

/****************************************************************************
 * Name: gpio_drive_low
 *
 * Description:
 *   Drive a GPIO pin low (open-drain style): configure as GPIO output
 *   with latch = 0.  Does NOT set the function register — caller must
 *   ensure the pin is in GPIO mode before calling this.
 *
 ****************************************************************************/

static void gpio_drive_low(int pin)
{
  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
  uint32_t cfg = getreg32(cfg_addr);

  cfg &= ~GPIO_CFG_SECOND_FUNC; /* clear second_func → GPIO mode */
  cfg |= GPIO_CFG_OUTPUT;       /* bit1 = 1: enable output register */
  cfg &= ~GPIO_CFG_OUTPUT_EN;   /* bit3 = 0: active-low → output enabled */
  cfg &= ~GPIO_CFG_INPUT;       /* latch = 0 (bit0 is input in GPIO mode) */

  putreg32(cfg, cfg_addr);
}

/****************************************************************************
 * Name: gpio_release
 *
 * Description:
 *   Release a GPIO pin to high-Z (input mode): set as GPIO input with
 *   output disabled.  External pull-up brings the line high.
 *
 ****************************************************************************/

static void gpio_release(int pin)
{
  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
  uint32_t cfg = getreg32(cfg_addr);

  cfg &= ~GPIO_CFG_SECOND_FUNC; /* GPIO mode */
  cfg &= ~GPIO_CFG_OUTPUT;      /* bit1 = 0: disable output register */
  cfg |= GPIO_CFG_OUTPUT_EN;    /* bit3 = 1: active-low → output disabled */
  cfg |= GPIO_CFG_INPUT_EN;     /* bit2 = 1: enable input buffer */

  putreg32(cfg, cfg_addr);
}

/****************************************************************************
 * Name: gpio_read_input
 *
 * Description:
 *   Read the current input level of a GPIO pin.  Returns true if high.
 *
 ****************************************************************************/

static bool gpio_read_input(int pin)
{
  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
  uint32_t cfg = getreg32(cfg_addr);
  return (cfg & GPIO_CFG_INPUT) != 0;
}

/****************************************************************************
 * Private Functions — SCCB Bit-Bang
 ****************************************************************************/

/****************************************************************************
 * Name: sccb_sda_low / sccb_sda_release
 *
 * Description:
 *   Control SDA line.  "Low" drives the pin low; "release" sets it to
 *   high-Z input so the pull-up brings it high.
 *
 ****************************************************************************/

static void sccb_sda_low(void)
{
  gpio_drive_low(g_cam_sda_pin);
}

static void sccb_sda_release(void)
{
  gpio_release(g_cam_sda_pin);
}

/****************************************************************************
 * Name: sccb_scl_low / sccb_scl_release
 *
 * Description:
 *   Control SCL line.  Same open-drain semantics as SDA.
 *
 ****************************************************************************/

static void sccb_scl_low(void)
{
  gpio_drive_low(g_cam_scl_pin);
}

static void sccb_scl_release(void)
{
  gpio_release(g_cam_scl_pin);
}

/****************************************************************************
 * Name: sccb_sda_read
 *
 * Description:
 *   Read the current SDA level.  Caller must have released SDA first.
 *
 ****************************************************************************/

static bool sccb_sda_read(void)
{
  return gpio_read_input(g_cam_sda_pin);
}

/****************************************************************************
 * Name: sccb_scl_wait_high
 *
 * Description:
 *   Wait for SCL to go high after releasing it.  Returns 0 on success,
 *   -ETIMEDOUT if SCL stays low beyond timeout (bus fault).
 *
 ****************************************************************************/

static int sccb_scl_wait_high(void)
{
  int timeout = SCCB_TIMEOUT_ITER;

  while (timeout-- > 0)
    {
      if (gpio_read_input(g_cam_scl_pin))
        {
          return 0;
        }

      up_udelay(SCCB_HALF_PERIOD_US);
    }

  syslog(LOG_ERR, "[camera] SCL stuck low — bus fault\n");
  return -ETIMEDOUT;
}

/****************************************************************************
 * Name: sccb_start
 *
 * Description:
 *   Generate an SCCB START condition: SDA goes low while SCL is high.
 *
 ****************************************************************************/

static void sccb_start(void)
{
  sccb_sda_release();
  sccb_scl_release();
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_sda_low();              /* SDA falls while SCL high = START */
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_low();
  up_udelay(SCCB_HALF_PERIOD_US);
}

/****************************************************************************
 * Name: sccb_stop
 *
 * Description:
 *   Generate an SCCB STOP condition: SDA goes high while SCL is high.
 *   Returns 0 on success, -ETIMEDOUT if SCL stays low (bus fault).
 *
 ****************************************************************************/

static int sccb_stop(void)
{
  int ret;

  sccb_sda_low();              /* ensure SDA is low before releasing SCL */
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_release();
  ret = sccb_scl_wait_high();  /* wait for SCL to actually go high */
  if (ret < 0)
    {
      return ret;
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_sda_release();          /* SDA rises while SCL high = STOP */
  up_udelay(SCCB_HALF_PERIOD_US);

  return 0;
}

/****************************************************************************
 * Name: sccb_write_byte
 *
 * Description:
 *   Write one byte over SCCB.  Returns 0 if ACK received, -EIO on NACK.
 *
 ****************************************************************************/

static int sccb_write_byte(uint8_t byte)
{
  int i;
  bool ack;

  /* Shift out 8 bits, MSB first */

  for (i = 7; i >= 0; i--)
    {
      if ((byte >> i) & 1)
        {
          sccb_sda_release();
        }
      else
        {
          sccb_sda_low();
        }

      up_udelay(SCCB_HALF_PERIOD_US);

      sccb_scl_release();
      if (sccb_scl_wait_high() < 0)
        {
          return -ETIMEDOUT;
        }

      up_udelay(SCCB_HALF_PERIOD_US);

      sccb_scl_low();
      up_udelay(SCCB_HALF_PERIOD_US);
    }

  /* Clock the ACK bit (9th clock) */

  sccb_sda_release();           /* release SDA for slave ACK */
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_release();
  if (sccb_scl_wait_high() < 0)
    {
      return -ETIMEDOUT;
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  ack = !sccb_sda_read();       /* ACK = SDA low */

  sccb_scl_low();
  up_udelay(SCCB_HALF_PERIOD_US);

  return ack ? 0 : -EIO;
}

/****************************************************************************
 * Name: sccb_read_byte
 *
 * Description:
 *   Read one byte over SCCB.  Sends ACK if ack=true, NACK if ack=false.
 *   Returns the byte value (0-255) on success, negative errno on failure.
 *
 ****************************************************************************/

static int sccb_read_byte(bool ack)
{
  uint8_t byte = 0;
  int i;

  sccb_sda_release();           /* release SDA for slave to drive */

  for (i = 7; i >= 0; i--)
    {
      up_udelay(SCCB_HALF_PERIOD_US);

      sccb_scl_release();
      if (sccb_scl_wait_high() < 0)
        {
          return -ETIMEDOUT;
        }

      up_udelay(SCCB_HALF_PERIOD_US);

      if (sccb_sda_read())
        {
          byte |= (1u << i);
        }

      sccb_scl_low();
      up_udelay(SCCB_HALF_PERIOD_US);
    }

  /* Send ACK/NACK (9th clock) */

  if (ack)
    {
      sccb_sda_low();           /* ACK = drive SDA low */
    }
  else
    {
      sccb_sda_release();       /* NACK = leave SDA high */
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_release();
  if (sccb_scl_wait_high() < 0)
    {
      return -ETIMEDOUT;
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_low();
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_sda_release();           /* release SDA after ACK/NACK */

  return (int)byte;
}

/****************************************************************************
 * Name: sccb_read_reg
 *
 * Description:
 *   Read one register from GC2145 at the given 8-bit address.
 *   SCCB protocol: START → [W phase] → STOP → START → [R phase] → STOP
 *   (SCCB requires a STOP between write and read phases, unlike I2C.)
 *
 *   Returns the register value (0-255) on success, negative errno on error.
 *
 ****************************************************************************/

static int sccb_read_reg(uint8_t reg_addr)
{
  int ret;
  int value;

  /* Phase 1: Write the register address (3-phase write) */

  sccb_start();

  ret = sccb_write_byte((uint8_t)(GC2145_SCCB_ADDR << 1) | 0);
  if (ret < 0)
    {
      goto stop_and_fail;
    }

  ret = sccb_write_byte(reg_addr);
  if (ret < 0)
    {
      goto stop_and_fail;
    }

  ret = sccb_stop();
  if (ret < 0)
    {
      return ret;
    }

  /* Phase 2: Read the register value (2-phase read) */

  sccb_start();

  ret = sccb_write_byte((uint8_t)(GC2145_SCCB_ADDR << 1) | 1);
  if (ret < 0)
    {
      goto stop_and_fail;
    }

  value = sccb_read_byte(false);  /* NACK to signal last byte */
  if (value < 0)
    {
      ret = value;
      goto stop_and_fail;
    }

  ret = sccb_stop();
  if (ret < 0)
    {
      return ret;
    }

  return value;

stop_and_fail:

  /* Best-effort STOP; if it fails the bus is already stuck */

  sccb_stop();
  return ret;
}

/****************************************************************************
 * Private Functions — MCLK
 ****************************************************************************/

/****************************************************************************
 * Name: mclk_save_state
 *
 * Description:
 *   Save the current MCLK register state before modification.
 *   Saves: clock source/divider (reg 0x0A), clock gate (reg 0x0D),
 *   P24-P31 function select (SYS_BASE+0xCC).
 *
 ****************************************************************************/

static void mclk_save_state(mclk_state_t *ms)
{
  ms->clk_div  = getreg32(CAMERA_CLK_DIV_REG);
  ms->clk_en   = getreg32(CAMERA_CLK_EN_REG);
  ms->func2431 = getreg32(CAMERA_GPIO_FUNC_REG);
  ms->valid    = true;
}

/****************************************************************************
 * Name: mclk_restore_state
 *
 * Description:
 *   Restore saved MCLK register state.  Disables the clock gate last
 *   to avoid glitches.
 *
 ****************************************************************************/

static void mclk_restore_state(const mclk_state_t *ms)
{
  if (!ms->valid)
    {
      return;
    }

  /* Restore source/divider first (harmless while gate is off) */

  putreg32(ms->clk_div, CAMERA_CLK_DIV_REG);

  /* Restore P27 pinmux */

  putreg32(ms->func2431, CAMERA_GPIO_FUNC_REG);

  /* Restore clock gate last */

  putreg32(ms->clk_en, CAMERA_CLK_EN_REG);
}

/****************************************************************************
 * Name: mclk_enable_24mhz
 *
 * Description:
 *   Configure and enable 24 MHz MCLK on P27.
 *
 *   Prerequisite: CONFIG_CAMERA_MCLK_CONFIRMED must be y.
 *   The caller has already validated the clock semantics.
 *
 ****************************************************************************/

static void mclk_enable_24mhz(void)
{
  uint32_t val;

  /* Set P27 function to CIS AUXS clock output (function 1) */

  val = getreg32(CAMERA_GPIO_FUNC_REG);
  val &= ~(CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
  val |= (CAMERA_P27_FUNC_CIS_CLK << CAMERA_P27_FUNC_SHIFT);
  putreg32(val, CAMERA_GPIO_FUNC_REG);

  /* Set clock source = 480 MHz PLL (cksel=3) and divider = 19 (24 MHz) */

  val = getreg32(CAMERA_CLK_DIV_REG);
  val &= ~((CAMERA_CKSEL_MASK << CAMERA_CKSEL_POS) |
           (CAMERA_CKDIV_MASK << CAMERA_CKDIV_POS));
  val |= (CAMERA_CKSEL_AUXS_CIS << CAMERA_CKSEL_POS);
  val |= (CAMERA_CKDIV_24MHZ    << CAMERA_CKDIV_POS);
  putreg32(val, CAMERA_CLK_DIV_REG);

  /* Enable the CIS AUXS clock gate */

  val = getreg32(CAMERA_CLK_EN_REG);
  val |= CAMERA_CIS_AUXS_CKEN_BIT;
  putreg32(val, CAMERA_CLK_EN_REG);
}

/****************************************************************************
 * Private Functions — Power Control
 ****************************************************************************/

/****************************************************************************
 * Name: camera_power_on
 *
 * Description:
 *   Assert power-on and deassert standby for the camera module.
 *   Handles active-high/active-low based on Kconfig.
 *   Skips lines whose GPIO is -1 (confirmed as not present).
 *
 ****************************************************************************/

static void camera_power_on(void)
{
  if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED)
    {
#ifdef CONFIG_CAMERA_PWR_ACTIVE_HIGH
      gpio_drive_low(g_cam_pwr_pin);   /* will be set high via output reg */
#else
      gpio_drive_low(g_cam_pwr_pin);   /* active-low: drive low = on */
#endif
      /* For Phase 0, just configure as GPIO output with appropriate level.
       * The actual output level is set via the latch bit in CFG.
       */
      uintptr_t cfg_addr = BK7258_GPIO_CFG(g_cam_pwr_pin);
      uint32_t cfg = getreg32(cfg_addr);

      cfg &= ~GPIO_CFG_SECOND_FUNC;
      cfg |= GPIO_CFG_OUTPUT;
      cfg &= ~GPIO_CFG_OUTPUT_EN;

#ifdef CONFIG_CAMERA_PWR_ACTIVE_HIGH
      cfg |= GPIO_CFG_INPUT;   /* latch = 1 → output high */
#else
      cfg &= ~GPIO_CFG_INPUT;  /* latch = 0 → output low */
#endif

      putreg32(cfg, cfg_addr);
      up_udelay(5000);  /* 5 ms for power rail to stabilize */
    }

  if (g_cam_pwdn_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      /* Deassert standby: PWDNB_ACTIVE_HIGH → drive low to exit standby
       *                   PWDNB_ACTIVE_LOW  → drive high to exit standby
       */

      uintptr_t cfg_addr = BK7258_GPIO_CFG(g_cam_pwdn_pin);
      uint32_t cfg = getreg32(cfg_addr);

      cfg &= ~GPIO_CFG_SECOND_FUNC;
      cfg |= GPIO_CFG_OUTPUT;
      cfg &= ~GPIO_CFG_OUTPUT_EN;

#ifdef CONFIG_CAMERA_PWDNB_ACTIVE_HIGH
      cfg &= ~GPIO_CFG_INPUT;  /* latch = 0 → low → not standby */
#else
      cfg |= GPIO_CFG_INPUT;   /* latch = 1 → high → not standby */
#endif

      putreg32(cfg, cfg_addr);
      up_udelay(1000);  /* 1 ms for sensor to exit standby */
    }
}

/****************************************************************************
 * Private Functions — Reset
 ****************************************************************************/

/****************************************************************************
 * Name: camera_reset
 *
 * Description:
 *   Assert then deassert hardware reset on DVP_RST.
 *   Assumes active-low (CONFIG_CAMERA_RST_ACTIVE_LOW=y is default).
 *   Assert = drive low for 10 ms, deassert = release (high-Z).
 *
 ****************************************************************************/

static void camera_reset(void)
{
  /* Assert reset (active-low: drive low) */

  gpio_drive_low(g_cam_rst_pin);
  up_udelay(10000);  /* 10 ms reset pulse (GC2145 datasheet: min 1 ms) */

  /* Deassert reset (release to high-Z; pull-up brings it high) */

  gpio_release(g_cam_rst_pin);
  up_udelay(5000);   /* 5 ms for sensor to initialize */
}

/****************************************************************************
 * Private Functions — Config Validation
 ****************************************************************************/

/****************************************************************************
 * Name: camera_check_config
 *
 * Description:
 *   Two-stage configuration validation before any MMIO access.
 *
 *   Stage 1: Check all "confirmed" bools from Kconfig.  These are
 *            independent of GPIO pin values — they gate whether we
 *            trust the board-level facts at all.
 *
 *   Stage 2: Validate GPIO pin values (range, uniqueness).
 *
 *   Returns 0 if all checks pass, -ENOTSUP if any blocker found.
 *   On failure, no hardware register has been touched.
 *
 ****************************************************************************/

static int camera_check_config(void)
{
  bool ok = true;

  syslog(LOG_INFO,
         "[camera] Board config:\n"
         "  SCCB_SDA  = %d  (confirmed=%s)\n"
         "  SCCB_SCL  = %d  (confirmed=%s)\n"
         "  DVP_RST   = %d  (confirmed=%s)\n"
         "  PWR_CTL   = %d  (confirmed=%s)\n"
         "  PWDNB     = %d  (confirmed=%s)\n"
         "  MCLK      = %d  (confirmed=%s)\n",
         g_cam_sda_pin,
#ifdef CONFIG_CAMERA_SCCB_CONFIRMED
         "y",
#else
         "n",
#endif
         g_cam_scl_pin,
#ifdef CONFIG_CAMERA_SCCB_CONFIRMED
         "y",
#else
         "n",
#endif
         g_cam_rst_pin,
#ifdef CONFIG_CAMERA_RST_CONFIRMED
         "y",
#else
         "n",
#endif
         g_cam_pwr_pin,
#ifdef CONFIG_CAMERA_PWR_CONFIRMED
         "y",
#else
         "n",
#endif
         g_cam_pwdn_pin,
#ifdef CONFIG_CAMERA_PWDNB_CONFIRMED
         "y",
#else
         "n",
#endif
         g_cam_mclk_pin,
#ifdef CONFIG_CAMERA_MCLK_CONFIRMED
         "y",
#else
         "n",
#endif
         );

  /* ---- Stage 1: confirmed sentinel checks ---- */

#ifndef CONFIG_CAMERA_SCCB_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: SCCB network NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_SCCB_CONFIRMED=y after verifying\n"
         "[camera]   SCL/SDA pin assignments from the product board.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_RST_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: DVP_RST NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_RST_CONFIRMED=y after verifying\n"
         "[camera]   the reset net and active level from the schematic.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_PWR_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: DVP_PWR_CTL NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_PWR_CONFIRMED=y after verifying\n"
         "[camera]   the power control net.  Use GPIO=-1 + confirmed=y\n"
         "[camera]   if power is always-on (no GPIO needed).\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_PWDNB_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: PWDNB NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_PWDNB_CONFIRMED=y after verifying\n"
         "[camera]   the standby net.  Use GPIO=-1 + confirmed=y if\n"
         "[camera]   PWDNB is hard-wired to a known state.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_MCLK_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: MCLK NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_MCLK_CONFIRMED=y only after:\n"
         "[camera]     - P27 verified as MCLK output on this board\n"
         "[camera]     - cksel=3 source confirmed as 480 MHz PLL\n"
         "[camera]     - divider semantics (ckdiv+1) confirmed\n"
         "[camera]     - no /2 pre-divider ambiguity remains\n");
  ok = false;
#endif

  if (!ok)
    {
      syslog(LOG_ERR,
             "[camera] ======== HARD BLOCKER(S) PRESENT ========\n"
             "[camera] No MMIO was accessed.  No GPIOs were modified.\n"
             "[camera] Fix all blockers above, then re-run.\n");
      return -ENOTSUP;
    }

  /* ---- Stage 2: GPIO pin value validation ---- */

  /* SCCB SDA must be in range */

  if (!gpio_is_valid(g_cam_sda_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: SCCB SDA pin %d is out of range "
             "(valid: %d-%d)\n",
             g_cam_sda_pin, CAMERA_GPIO_MIN, CAMERA_GPIO_MAX);
      ok = false;
    }

  /* SCCB SCL must be in range */

  if (!gpio_is_valid(g_cam_scl_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: SCCB SCL pin %d is out of range "
             "(valid: %d-%d)\n",
             g_cam_scl_pin, CAMERA_GPIO_MIN, CAMERA_GPIO_MAX);
      ok = false;
    }

  /* SDA and SCL must be different pins */

  if (gpio_is_valid(g_cam_sda_pin) && gpio_is_valid(g_cam_scl_pin) &&
      g_cam_sda_pin == g_cam_scl_pin)
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: SDA and SCL are the same pin (%d)\n",
             g_cam_sda_pin);
      ok = false;
    }

  /* RST must be in range if configured (GPIO != -1) */

  if (g_cam_rst_pin != CAMERA_GPIO_UNCONFIGURED &&
      !gpio_is_valid(g_cam_rst_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: DVP_RST pin %d is out of range\n",
             g_cam_rst_pin);
      ok = false;
    }

  /* RST must not conflict with SDA or SCL */

  if (g_cam_rst_pin != CAMERA_GPIO_UNCONFIGURED &&
      (g_cam_rst_pin == g_cam_sda_pin || g_cam_rst_pin == g_cam_scl_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: DVP_RST pin %d conflicts with SCCB\n",
             g_cam_rst_pin);
      ok = false;
    }

  /* PWR_CTL must be in range if configured */

  if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED &&
      !gpio_is_valid(g_cam_pwr_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: PWR_CTL pin %d is out of range\n",
             g_cam_pwr_pin);
      ok = false;
    }

  /* PWDNB must be in range if configured */

  if (g_cam_pwdn_pin != CAMERA_GPIO_UNCONFIGURED &&
      !gpio_is_valid(g_cam_pwdn_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: PWDNB pin %d is out of range\n",
             g_cam_pwdn_pin);
      ok = false;
    }

  /* MCLK must be in range if configured */

  if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED &&
      !gpio_is_valid(g_cam_mclk_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: MCLK pin %d is out of range\n",
             g_cam_mclk_pin);
      ok = false;
    }

  /* All configured GPIOs must be unique (no pin sharing) */

  {
    int pins[6];
    int n = 0;
    int i, j;

    if (gpio_is_valid(g_cam_sda_pin))  pins[n++] = g_cam_sda_pin;
    if (gpio_is_valid(g_cam_scl_pin))  pins[n++] = g_cam_scl_pin;
    if (g_cam_rst_pin != CAMERA_GPIO_UNCONFIGURED &&
        gpio_is_valid(g_cam_rst_pin))  pins[n++] = g_cam_rst_pin;
    if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED &&
        gpio_is_valid(g_cam_pwr_pin))  pins[n++] = g_cam_pwr_pin;
    if (g_cam_pwdn_pin != CAMERA_GPIO_UNCONFIGURED &&
        gpio_is_valid(g_cam_pwdn_pin)) pins[n++] = g_cam_pwdn_pin;
    if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED &&
        gpio_is_valid(g_cam_mclk_pin)) pins[n++] = g_cam_mclk_pin;

    for (i = 0; i < n; i++)
      {
        for (j = i + 1; j < n; j++)
          {
            if (pins[i] == pins[j])
              {
                syslog(LOG_ERR,
                       "[camera] BLOCKER: GPIO %d is assigned to "
                       "multiple roles\n", pins[i]);
                ok = false;
              }
          }
      }
  }

  if (!ok)
    {
      syslog(LOG_ERR,
             "[camera] Cannot proceed — fix blockers above.\n"
             "[camera] No MMIO was accessed.  No GPIOs were modified.\n");
      return -ENODEV;
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_camera_id
 *
 * Description:
 *   Phase 0 "camera id" command.  Reads GC2145 registers 0xF0 and 0xF1
 *   via open-drain SCCB bit-bang and prints the chip ID.
 *
 *   Safety: two-stage config validation before any MMIO access.
 *   Stage 1 checks all "confirmed" sentinels; stage 2 validates GPIO
 *   pin values.  If any check fails, no hardware is touched.
 *
 * Returns:
 *   0 on success (ID matches 0x2145), negative errno on failure.
 *
 ****************************************************************************/

int bk7258_camera_id(void)
{
  gpio_state_t sda_saved;
  gpio_state_t scl_saved;
  gpio_state_t rst_saved;
  mclk_state_t mclk_saved = { .valid = false };
  int id_h = -1;
  int id_l = -1;
  uint16_t chip_id;
  int ret;
  bool sda_saved_ok = false;
  bool scl_saved_ok = false;
  bool rst_saved_ok = false;
  bool mclk_on = false;
  bool powered = false;

  /* ================================================================
   * Stage 1 & 2: Config validation — NO MMIO before this point.
   * ================================================================ */

  ret = camera_check_config();
  if (ret < 0)
    {
      return ret;
    }

  syslog(LOG_INFO,
         "[camera] Config OK — proceeding with SCCB ID read\n");

  /* ================================================================
   * GPIO setup: save pinmux, configure for SCCB/power/reset.
   * From this point onward we touch hardware.
   * ================================================================ */

  /* Save SCCB pin states (mux + direction) */

  gpio_save_state(g_cam_sda_pin, &sda_saved);
  sda_saved_ok = true;

  gpio_save_state(g_cam_scl_pin, &scl_saved);
  scl_saved_ok = true;

  /* Set SDA and SCL to GPIO mode, released (high-Z) */

  gpio_release(g_cam_sda_pin);
  gpio_release(g_cam_scl_pin);
  up_udelay(100);  /* let lines settle */

  /* If RST is configured, save its state and assert reset later */

  if (g_cam_rst_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      gpio_save_state(g_cam_rst_pin, &rst_saved);
      rst_saved_ok = true;
    }

  /* Enable power (if power GPIO is configured) */

  camera_power_on();
  powered = true;

  /* Enable MCLK (if confirmed and GPIO configured) */

  if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      mclk_save_state(&mclk_saved);
      mclk_enable_24mhz();
      mclk_on = true;
      up_udelay(500);  /* 500 µs for PLL lock */
    }

  /* Hardware reset (if RST GPIO is configured) */

  if (rst_saved_ok)
    {
      camera_reset();
    }

  /* ================================================================
   * SCCB ID read
   * ================================================================ */

  /* Read chip ID high byte (register 0xF0) */

  id_h = sccb_read_reg(GC2145_REG_ID_H);
  if (id_h < 0)
    {
      syslog(LOG_ERR,
             "[camera] Failed to read ID high byte: %d\n", id_h);
      ret = id_h;
      goto cleanup;
    }

  /* Read chip ID low byte (register 0xF1) */

  id_l = sccb_read_reg(GC2145_REG_ID_L);
  if (id_l < 0)
    {
      syslog(LOG_ERR,
             "[camera] Failed to read ID low byte: %d\n", id_l);
      ret = id_l;
      goto cleanup;
    }

  chip_id = (uint16_t)((id_h << 8) | id_l);

  syslog(LOG_INFO,
         "[camera] GC2145 chip ID: 0x%04X "
         "(reg 0xF0=0x%02X, reg 0xF1=0x%02X)\n",
         chip_id, (uint8_t)id_h, (uint8_t)id_l);

  if (chip_id == 0x2145)
    {
      syslog(LOG_INFO,
             "[camera] ID match: GC2145 confirmed.\n");
      ret = 0;
    }
  else
    {
      syslog(LOG_ERR,
             "[camera] ID mismatch: expected 0x2145, got 0x%04X\n",
             chip_id);
      ret = -ENODEV;
    }

cleanup:

  /* ================================================================
   * Cleanup: restore all GPIO states.  Order matters:
   *   1. Stop SCCB bus (best-effort STOP condition)
   *   2. Disable MCLK and restore clock registers
   *   3. Release power/standby pins
   *   4. Restore GPIO pinmux for all saved pins
   * ================================================================ */

  /* Best-effort SCCB stop (if bus was started) */

  sccb_stop();

  /* Disable MCLK and restore clock registers */

  if (mclk_on)
    {
      mclk_restore_state(&mclk_saved);
    }

  /* Release RST (restore to original state) */

  if (rst_saved_ok)
    {
      gpio_restore_state(&rst_saved);
    }

  /* Release SCCB pins (restore to original state) */

  if (scl_saved_ok)
    {
      gpio_restore_state(&scl_saved);
    }

  if (sda_saved_ok)
    {
      gpio_restore_state(&sda_saved);
    }

  syslog(LOG_INFO,
         "[camera] GPIO cleanup complete — all pins restored.\n");

  return ret;
}

