222	static void gpio_save_state(int pin, gpio_state_t *s)
223	{
224	  s->cfg_addr  = BK7258_GPIO_CFG(pin);
225	  s->func_addr = BK7258_SYS_GPIO_FUNC(pin);
226	  s->cfg       = getreg32(s->cfg_addr);
227	  s->func      = getreg32(s->func_addr);
228	}
229	
230	/****************************************************************************
231	 * Name: gpio_restore_state
232	 *
233	 * Description:
234	 *   Restore a previously saved GPIO state.
235	 *
236	 ****************************************************************************/
237	
238	static void gpio_restore_state(const gpio_state_t *s)
239	{
240	  putreg32(s->cfg, s->cfg_addr);
241	  putreg32(s->func, s->func_addr);
242	}
