244	/****************************************************************************
245	 * Name: gpio_drive_low
246	 *
247	 * Description:
248	 *   Drive a GPIO pin low (open-drain style): configure as GPIO output
249	 *   with latch = 0.  Does NOT set the function register — caller must
250	 *   ensure the pin is in GPIO mode before calling this.
251	 *
252	 ****************************************************************************/
253	
254	static void gpio_drive_low(int pin)
255	{
256	  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
257	  uint32_t cfg = getreg32(cfg_addr);
258	
259	  cfg &= ~GPIO_CFG_SECOND_FUNC; /* clear second_func → GPIO mode */
260	  cfg |= GPIO_CFG_OUTPUT;       /* bit1 = 1: enable output register */
261	  cfg &= ~GPIO_CFG_OUTPUT_EN;   /* bit3 = 0: active-low → output enabled */
262	  cfg &= ~GPIO_CFG_INPUT;       /* latch = 0 (bit0 is input in GPIO mode) */
263	
264	  putreg32(cfg, cfg_addr);
265	}
266	
267	/****************************************************************************
268	 * Name: gpio_release
269	 *
270	 * Description:
271	 *   Release a GPIO pin to high-Z (input mode): set as GPIO input with
272	 *   output disabled.  External pull-up brings the line high.
273	 *
274	 ****************************************************************************/
275	
276	static void gpio_release(int pin)
277	{
278	  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
279	  uint32_t cfg = getreg32(cfg_addr);
280	
281	  cfg &= ~GPIO_CFG_SECOND_FUNC; /* GPIO mode */
282	  cfg &= ~GPIO_CFG_OUTPUT;      /* bit1 = 0: disable output register */
283	  cfg |= GPIO_CFG_OUTPUT_EN;    /* bit3 = 1: active-low → output disabled */
284	  cfg |= GPIO_CFG_INPUT_EN;     /* bit2 = 1: enable input buffer */
285	
286	  putreg32(cfg, cfg_addr);
287	}
