295	 ****************************************************************************/
296	
297	static bool gpio_read_input(int pin)
298	{
299	  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
300	  uint32_t cfg = getreg32(cfg_addr);
301	  return (cfg & GPIO_CFG_INPUT) != 0;
302	}
