304	/****************************************************************************
305	 * Private Functions — SCCB Bit-Bang
306	 ****************************************************************************/
307	
308	/****************************************************************************
309	 * Name: sccb_sda_low / sccb_sda_release
310	 *
311	 * Description:
312	 *   Control SDA line.  "Low" drives the pin low; "release" sets it to
313	 *   high-Z input so the pull-up brings it high.
314	 *
315	 ****************************************************************************/
316	
317	static void sccb_sda_low(void)
318	{
319	  gpio_drive_low(g_cam_sda_pin);
320	}
321	
322	static void sccb_sda_release(void)
323	{
324	  gpio_release(g_cam_sda_pin);
325	}
326	
327	/****************************************************************************
328	 * Name: sccb_scl_low / sccb_scl_release
329	 *
330	 * Description:
331	 *   Control SCL line.  Same open-drain semantics as SDA.
332	 *
333	 ****************************************************************************/
334	
335	static void sccb_scl_low(void)
336	{
337	  gpio_drive_low(g_cam_scl_pin);
338	}
339	
340	static void sccb_scl_release(void)
341	{
342	  gpio_release(g_cam_scl_pin);
343	}
