345	/****************************************************************************
346	 * Name: sccb_sda_read
347	 *
348	 * Description:
349	 *   Read the current SDA level.  Caller must have released SDA first.
350	 *
351	 ****************************************************************************/
352	
353	static bool sccb_sda_read(void)
354	{
355	  return gpio_read_input(g_cam_sda_pin);
356	}
357	
358	/****************************************************************************
359	 * Name: sccb_scl_wait_high
360	 *
361	 * Description:
362	 *   Wait for SCL to go high after releasing it.  Returns 0 on success,
363	 *   -ETIMEDOUT if SCL stays low beyond timeout (bus fault).
364	 *
365	 ****************************************************************************/
366	
367	static int sccb_scl_wait_high(void)
368	{
369	  int timeout = SCCB_TIMEOUT_ITER;
370	
371	  while (timeout-- > 0)
372	    {
373	      if (gpio_read_input(g_cam_scl_pin))
374	        {
375	          return 0;
376	        }
377	
378	      up_udelay(SCCB_HALF_PERIOD_US);
379	    }
380	
381	  syslog(LOG_ERR, "[camera] SCL stuck low — bus fault\n");
382	  return -ETIMEDOUT;
383	}
384	
385	/****************************************************************************
386	 * Name: sccb_start
387	 *
388	 * Description:
389	 *   Generate an SCCB START condition: SDA goes low while SCL is high.
390	 *
391	 ****************************************************************************/
392	
393	static void sccb_start(void)
394	{
395	  sccb_sda_release();
396	  sccb_scl_release();
397	  up_udelay(SCCB_HALF_PERIOD_US);
398	
399	  sccb_sda_low();              /* SDA falls while SCL high = START */
400	  up_udelay(SCCB_HALF_PERIOD_US);
401	
402	  sccb_scl_low();
403	  up_udelay(SCCB_HALF_PERIOD_US);
404	}
405	
406	/****************************************************************************
407	 * Name: sccb_stop
408	 *
409	 * Description:
410	 *   Generate an SCCB STOP condition: SDA goes high while SCL is high.
411	 *   Returns 0 on success, -ETIMEDOUT if SCL stays low (bus fault).
412	 *
413	 ****************************************************************************/
414	
415	static int sccb_stop(void)
416	{
417	  int ret;
418	
419	  sccb_sda_low();              /* ensure SDA is low before releasing SCL */

415	static int sccb_stop(void)
416	{
417	  int ret;
418	
419	  sccb_sda_low();              /* ensure SDA is low before releasing SCL */
420	  up_udelay(SCCB_HALF_PERIOD_US);
421	
422	  sccb_scl_release();
423	  ret = sccb_scl_wait_high();  /* wait for SCL to actually go high */
424	  if (ret < 0)
425	    {
426	      return ret;
427	    }
428	
429	  up_udelay(SCCB_HALF_PERIOD_US);
430	
431	  sccb_sda_release();          /* SDA rises while SCL high = STOP */
432	  up_udelay(SCCB_HALF_PERIOD_US);
433	
434	  return 0;
435	}
436	
437	/****************************************************************************
438	 * Name: sccb_write_byte
439	 *
440	 * Description:
441	 *   Write one byte over SCCB.  Returns 0 if ACK received, -EIO on NACK.
442	 *
443	 ****************************************************************************/
444	
445	static int sccb_write_byte(uint8_t byte)
446	{
447	  int i;
448	  bool ack;
449	
450	  /* Shift out 8 bits, MSB first */
451	
452	  for (i = 7; i >= 0; i--)
453	    {
454	      if ((byte >> i) & 1)
455	        {
456	          sccb_sda_release();
457	        }
458	      else
459	        {
460	          sccb_sda_low();
461	        }
462	
463	      up_udelay(SCCB_HALF_PERIOD_US);
464	
465	      sccb_scl_release();
466	      if (sccb_scl_wait_high() < 0)
467	        {
468	          return -ETIMEDOUT;
469	        }
470	
471	      up_udelay(SCCB_HALF_PERIOD_US);
472	
473	      sccb_scl_low();
474	      up_udelay(SCCB_HALF_PERIOD_US);
475	    }
476	
477	  /* Clock the ACK bit (9th clock) */
478	
479	  sccb_sda_release();           /* release SDA for slave ACK */
480	  up_udelay(SCCB_HALF_PERIOD_US);
481	
482	  sccb_scl_release();
483	  if (sccb_scl_wait_high() < 0)
484	    {
485	      return -ETIMEDOUT;
486	    }
487	
488	  up_udelay(SCCB_HALF_PERIOD_US);
489	
490	  ack = !sccb_sda_read();       /* ACK = SDA low */
491	
492	  sccb_scl_low();
493	  up_udelay(SCCB_HALF_PERIOD_US);
494	
495	  return ack ? 0 : -EIO;
496	}
497	
498	/****************************************************************************
499	 * Name: sccb_read_byte
500	 *
501	 * Description:
502	 *   Read one byte over SCCB.  Sends ACK if ack=true, NACK if ack=false.
503	 *   Returns the byte value (0-255) on success, negative errno on failure.
504	 *
505	 ****************************************************************************/
506	
507	static int sccb_read_byte(bool ack)
508	{
509	  uint8_t byte = 0;
510	  int i;
511	
512	  sccb_sda_release();           /* release SDA for slave to drive */
513	
514	  for (i = 7; i >= 0; i--)
515	    {
516	      up_udelay(SCCB_HALF_PERIOD_US);
517	
518	      sccb_scl_release();
519	      if (sccb_scl_wait_high() < 0)
520	        {
521	          return -ETIMEDOUT;
522	        }
523	
524	      up_udelay(SCCB_HALF_PERIOD_US);
525	
526	      if (sccb_sda_read())
527	        {
528	          byte |= (1u << i);
529	        }
530	
531	      sccb_scl_low();
532	      up_udelay(SCCB_HALF_PERIOD_US);
533	    }
534	
535	  /* Send ACK/NACK (9th clock) */
536	
537	  if (ack)
538	    {
539	      sccb_sda_low();           /* ACK = drive SDA low */
540	    }
541	  else
542	    {
543	      sccb_sda_release();       /* NACK = leave SDA high */
544	    }
545	
546	  up_udelay(SCCB_HALF_PERIOD_US);
547	
548	  sccb_scl_release();
549	  if (sccb_scl_wait_high() < 0)
550	    {
551	      return -ETIMEDOUT;
552	    }
553	
554	  up_udelay(SCCB_HALF_PERIOD_US);
555	
556	  sccb_scl_low();
557	  up_udelay(SCCB_HALF_PERIOD_US);
558	
559	  sccb_sda_release();           /* release SDA after ACK/NACK */
560	
561	  return (int)byte;
562	}
563	
564	/****************************************************************************
565	 * Name: sccb_read_reg
566	 *
567	 * Description:
568	 *   Read one register from GC2145 at the given 8-bit address.
569	 *   SCCB protocol: START → [W phase] → STOP → START → [R phase] → STOP
570	 *   (SCCB requires a STOP between write and read phases, unlike I2C.)
571	 *
572	 *   Returns the register value (0-255) on success, negative errno on error.
573	 *
574	 ****************************************************************************/
575	
576	static int sccb_read_reg(uint8_t reg_addr)
577	{
578	  int ret;
579	  int value;
580	
581	  /* Phase 1: Write the register address (3-phase write) */
582	
583	  sccb_start();
584	
585	  ret = sccb_write_byte((uint8_t)(GC2145_SCCB_ADDR << 1) | 0);
586	  if (ret < 0)
587	    {
588	      goto stop_and_fail;
589	    }
590	
591	  ret = sccb_write_byte(reg_addr);
592	  if (ret < 0)
593	    {
594	      goto stop_and_fail;
595	    }
596	
597	  ret = sccb_stop();
598	  if (ret < 0)
599	    {
600	      return ret;
601	    }
602	
603	  /* Phase 2: Read the register value (2-phase read) */
604	
605	  sccb_start();
606	
607	  ret = sccb_write_byte((uint8_t)(GC2145_SCCB_ADDR << 1) | 1);
608	  if (ret < 0)
609	    {
610	      goto stop_and_fail;
611	    }
612	
613	  value = sccb_read_byte(false);  /* NACK to signal last byte */
614	  if (value < 0)

614	  if (value < 0)
615	    {
616	      ret = value;
617	      goto stop_and_fail;
618	    }
619	
620	  ret = sccb_stop();
621	  if (ret < 0)
622	    {
623	      return ret;
624	    }
625	
626	  return value;
627	
628	stop_and_fail:
629	
630	  /* Best-effort STOP; if it fails the bus is already stuck */
631	
632	  sccb_stop();
633	  return ret;
634	}
635	
636	/****************************************************************************
637	 * Private Functions — MCLK
638	 ****************************************************************************/
639	
640	/****************************************************************************
641	 * Name: mclk_save_state
642	 *
643	 * Description:
644	 *   Save the current MCLK register state before modification.
645	 *   Saves: clock source/divider (reg 0x0A), clock gate (reg 0x0D),
646	 *   P24-P31 function select (SYS_BASE+0xCC).
647	 *
648	 ****************************************************************************/
649	
650	static void mclk_save_state(mclk_state_t *ms)
651	{
652	  ms->clk_div  = getreg32(CAMERA_CLK_DIV_REG);
653	  ms->clk_en   = getreg32(CAMERA_CLK_EN_REG);
654	  ms->func2431 = getreg32(CAMERA_GPIO_FUNC_REG);
655	  ms->valid    = true;
656	}
657	
658	/****************************************************************************
659	 * Name: mclk_restore_state
660	 *
661	 * Description:
662	 *   Restore saved MCLK register state.  Disables the clock gate last
663	 *   to avoid glitches.
664	 *
665	 ****************************************************************************/
666	
667	static void mclk_restore_state(const mclk_state_t *ms)
668	{
669	  if (!ms->valid)
670	    {
671	      return;
672	    }
673	
674	  /* Restore source/divider first (harmless while gate is off) */
675	
676	  putreg32(ms->clk_div, CAMERA_CLK_DIV_REG);
677	
678	  /* Restore P27 pinmux */
679	
680	  putreg32(ms->func2431, CAMERA_GPIO_FUNC_REG);
681	
682	  /* Restore clock gate last */
683	
684	  putreg32(ms->clk_en, CAMERA_CLK_EN_REG);
685	}
686	
687	/****************************************************************************
688	 * Name: mclk_enable_24mhz
689	 *
690	 * Description:
691	 *   Configure and enable 24 MHz MCLK on P27.
692	 *
693	 *   Prerequisite: CONFIG_CAMERA_MCLK_CONFIRMED must be y.
694	 *   The caller has already validated the clock semantics.
695	 *
696	 ****************************************************************************/
697	
698	static void mclk_enable_24mhz(void)
699	{
700	  uint32_t val;
701	
702	  /* Set P27 function to CIS AUXS clock output (function 1) */
703	
704	  val = getreg32(CAMERA_GPIO_FUNC_REG);
705	  val &= ~(CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
706	  val |= (CAMERA_P27_FUNC_CIS_CLK << CAMERA_P27_FUNC_SHIFT);
707	  putreg32(val, CAMERA_GPIO_FUNC_REG);
708	
709	  /* Set clock source = 480 MHz PLL (cksel=3) and divider = 19 (24 MHz) */
710	
711	  val = getreg32(CAMERA_CLK_DIV_REG);
712	  val &= ~((CAMERA_CKSEL_MASK << CAMERA_CKSEL_POS) |
713	           (CAMERA_CKDIV_MASK << CAMERA_CKDIV_POS));
714	  val |= (CAMERA_CKSEL_AUXS_CIS << CAMERA_CKSEL_POS);
715	  val |= (CAMERA_CKDIV_24MHZ    << CAMERA_CKDIV_POS);
716	  putreg32(val, CAMERA_CLK_DIV_REG);
717	
718	  /* Enable the CIS AUXS clock gate */
719	
720	  val = getreg32(CAMERA_CLK_EN_REG);
721	  val |= CAMERA_CIS_AUXS_CKEN_BIT;
722	  putreg32(val, CAMERA_CLK_EN_REG);
723	}
724	
725	/****************************************************************************
726	 * Private Functions — Power Control
727	 ****************************************************************************/
728	
729	/****************************************************************************
730	 * Name: camera_power_on
731	 *
732	 * Description:
733	 *   Assert power-on and deassert standby for the camera module.
734	 *   Handles active-high/active-low based on Kconfig.
735	 *   Skips lines whose GPIO is -1 (confirmed as not present).
736	 *
737	 ****************************************************************************/
738	
739	static void camera_power_on(void)
740	{
741	  if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED)
742	    {
743	#ifdef CONFIG_CAMERA_PWR_ACTIVE_HIGH
744	      gpio_drive_low(g_cam_pwr_pin);   /* will be set high via output reg */
745	#else
746	      gpio_drive_low(g_cam_pwr_pin);   /* active-low: drive low = on */
747	#endif
748	      /* For Phase 0, just configure as GPIO output with appropriate level.
749	       * The actual output level is set via the latch bit in CFG.
750	       */
751	      uintptr_t cfg_addr = BK7258_GPIO_CFG(g_cam_pwr_pin);
752	      uint32_t cfg = getreg32(cfg_addr);
753	
754	      cfg &= ~GPIO_CFG_SECOND_FUNC;
755	      cfg |= GPIO_CFG_OUTPUT;
756	      cfg &= ~GPIO_CFG_OUTPUT_EN;
757	
758	#ifdef CONFIG_CAMERA_PWR_ACTIVE_HIGH
759	      cfg |= GPIO_CFG_INPUT;   /* latch = 1 → output high */
760	#else
761	      cfg &= ~GPIO_CFG_INPUT;  /* latch = 0 → output low */
762	#endif
763	
764	      putreg32(cfg, cfg_addr);
765	      up_udelay(5000);  /* 5 ms for power rail to stabilize */
766	    }
767	
768	  if (g_cam_pwdn_pin != CAMERA_GPIO_UNCONFIGURED)
769	    {
770	      /* Deassert standby: PWDNB_ACTIVE_HIGH → drive low to exit standby
771	       *                   PWDNB_ACTIVE_LOW  → drive high to exit standby
772	       */
773	
774	      uintptr_t cfg_addr = BK7258_GPIO_CFG(g_cam_pwdn_pin);
775	      uint32_t cfg = getreg32(cfg_addr);
776	
777	      cfg &= ~GPIO_CFG_SECOND_FUNC;
778	      cfg |= GPIO_CFG_OUTPUT;
779	      cfg &= ~GPIO_CFG_OUTPUT_EN;
780	
781	#ifdef CONFIG_CAMERA_PWDNB_ACTIVE_HIGH
782	      cfg &= ~GPIO_CFG_INPUT;  /* latch = 0 → low → not standby */
783	#else
784	      cfg |= GPIO_CFG_INPUT;   /* latch = 1 → high → not standby */
785	#endif
786	
787	      putreg32(cfg, cfg_addr);
788	      up_udelay(1000);  /* 1 ms for sensor to exit standby */
789	    }
790	}
791	
792	/****************************************************************************
793	 * Private Functions — Reset
794	 ****************************************************************************/
795	
796	/****************************************************************************
797	 * Name: camera_reset
798	 *
799	 * Description:
800	 *   Assert then deassert hardware reset on DVP_RST.
801	 *   Assumes active-low (CONFIG_CAMERA_RST_ACTIVE_LOW=y is default).
802	 *   Assert = drive low for 10 ms, deassert = release (high-Z).
803	 *
804	 ****************************************************************************/
805	
806	static void camera_reset(void)
807	{
808	  /* Assert reset (active-low: drive low) */
809	
810	  gpio_drive_low(g_cam_rst_pin);
811	  up_udelay(10000);  /* 10 ms reset pulse (GC2145 datasheet: min 1 ms) */
812	
813	  /* Deassert reset (release to high-Z; pull-up brings it high) */

