/****************************************************************************
 * GC2145 Phase 0 — "camera id" command
 *
 * Reads the GC2145 chip ID registers (0xF0 → 0x21, 0xF1 → 0x45) via
 * open-drain SCCB bit-bang.  Does NOT implement video capture.
 *
 * Safety:
 *   Stage 1 — Check all "confirmed" bools (9 sentinels).  If ANY are n,
 *             return -ENOTSUP without touching any hardware register.
 *   Stage 2 — Validate GPIO pin values (range, uniqueness, conflicts
 *             with UART/SWD/LCD).
 *   Stage 3 — For MCLK: enforce MCLK_GPIO == 27 when confirmed.
 *
 * All GPIO operations save/restore original state on cleanup.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/arch.h>

#include "bk7258_gpio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define CAMERA_GPIO_UNCONFIGURED  (-1)
#define CAMERA_GPIO_MIN           0
#define CAMERA_GPIO_MAX           47

/* GC2145 chip ID */

#define GC2145_REG_ID_H    0xf0
#define GC2145_REG_ID_L    0xf1
#define GC2145_ID_H        0x21
#define GC2145_ID_L        0x45
#define GC2145_SCCB_ADDR   0x3c

/* BK7258 DVP MCLK registers (ARMino Apache-2.0 reference) */

#define CAMERA_SYS_BASE           0x44010000u
#define CAMERA_CLK_DIV_REG        (CAMERA_SYS_BASE + 0x28u)
#define CAMERA_CKSEL_AUXS_CIS     3u
#define CAMERA_CKDIV_24MHZ        19u
#define CAMERA_CKSEL_POS          15u
#define CAMERA_CKSEL_MASK         0x3u
#define CAMERA_CKDIV_POS          17u
#define CAMERA_CKDIV_MASK         0x1fu
#define CAMERA_CLK_EN_REG         (CAMERA_SYS_BASE + 0x34u)
#define CAMERA_CIS_AUXS_CKEN_BIT  (1u << 9)
#define CAMERA_GPIO_FUNC_REG      (CAMERA_SYS_BASE + 0xCCu)
#define CAMERA_P27_FUNC_SHIFT     12u
#define CAMERA_P27_FUNC_MASK      0xFu
#define CAMERA_P27_FUNC_CIS_CLK   1u

/* P27 GPIO CFG register (for save/restore of pin-level state) */

#define CAMERA_P27_CFG_REG        BK7258_GPIO_CFG(27)

/* The only supported MCLK pin */

#define CAMERA_MCLK_REQUIRED_PIN  27

/* SCCB timing */

#define SCCB_HALF_PERIOD_US  5
#define SCCB_TIMEOUT_ITER    1000

/* Reserved pin ranges for conflict checking */

#define CAMERA_PIN_UART0_RX   10
#define CAMERA_PIN_UART0_TX   11
#define CAMERA_PIN_SWD_CLK    20
#define CAMERA_PIN_SWD_IO     21

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef struct
{
  uint32_t cfg;
  uint32_t func;
  uintptr_t cfg_addr;
  uintptr_t func_addr;
} gpio_state_t;

/* MCLK register state — saves ALL registers touched by mclk_enable,
 * plus the P27 GPIO CFG register for pin-level restore.
 */

typedef struct
{
  uint32_t clk_div;       /* reg 0x0A: source + divider */
  uint32_t clk_en;        /* reg 0x0D: clock gate */
  uint32_t func2431;      /* SYS_BASE+0xCC: P24-P31 function select */
  uint32_t p27_cfg;       /* BK7258_GPIO_CFG(27): pin direction/latch */
  bool     valid;
} mclk_state_t;

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const int g_cam_sda_pin  = CONFIG_CAMERA_GPIO_SDA;
static const int g_cam_scl_pin  = CONFIG_CAMERA_GPIO_SCL;
static const int g_cam_rst_pin  = CONFIG_CAMERA_GPIO_RST;
static const int g_cam_pwr_pin  = CONFIG_CAMERA_GPIO_PWR_CTL;
static const int g_cam_pwdn_pin = CONFIG_CAMERA_GPIO_PWDNB;
static const int g_cam_mclk_pin = CONFIG_CAMERA_MCLK_GPIO;

/****************************************************************************
 * Private Functions — GPIO Helpers
 ****************************************************************************/

static inline bool gpio_is_valid(int pin)
{
  return pin >= CAMERA_GPIO_MIN && pin <= CAMERA_GPIO_MAX;
}

static void gpio_save_state(int pin, gpio_state_t *s)
{
  s->cfg_addr  = BK7258_GPIO_CFG(pin);
  s->func_addr = BK7258_SYS_GPIO_FUNC(pin);
  s->cfg       = getreg32(s->cfg_addr);
  s->func      = getreg32(s->func_addr);
}

static void gpio_restore_state(const gpio_state_t *s)
{
  putreg32(s->cfg, s->cfg_addr);
  putreg32(s->func, s->func_addr);
}

static void gpio_drive_low(int pin)
{
  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
  uint32_t cfg = getreg32(cfg_addr);

  cfg &= ~GPIO_CFG_SECOND_FUNC;
  cfg |= GPIO_CFG_OUTPUT;
  cfg &= ~GPIO_CFG_OUTPUT_EN;
  cfg &= ~GPIO_CFG_INPUT;

  putreg32(cfg, cfg_addr);
}

static void gpio_release(int pin)
{
  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
  uint32_t cfg = getreg32(cfg_addr);

  cfg &= ~GPIO_CFG_SECOND_FUNC;
  cfg &= ~GPIO_CFG_OUTPUT;
  cfg |= GPIO_CFG_OUTPUT_EN;
  cfg |= GPIO_CFG_INPUT_EN;

  putreg32(cfg, cfg_addr);
}

static void gpio_set_output_high(int pin)
{
  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
  uint32_t cfg = getreg32(cfg_addr);

  cfg &= ~GPIO_CFG_SECOND_FUNC;
  cfg |= GPIO_CFG_OUTPUT;
  cfg &= ~GPIO_CFG_OUTPUT_EN;
  cfg |= GPIO_CFG_INPUT;  /* latch = 1 → output high */

  putreg32(cfg, cfg_addr);
}

static bool gpio_read_input(int pin)
{
  uintptr_t cfg_addr = BK7258_GPIO_CFG(pin);
  uint32_t cfg = getreg32(cfg_addr);
  return (cfg & GPIO_CFG_INPUT) != 0;
}

/****************************************************************************
 * Private Functions — SCCB Bit-Bang
 ****************************************************************************/

static void sccb_sda_low(void)
{
  gpio_drive_low(g_cam_sda_pin);
}

static void sccb_sda_release(void)
{
  gpio_release(g_cam_sda_pin);
}

static void sccb_scl_low(void)
{
  gpio_drive_low(g_cam_scl_pin);
}

static void sccb_scl_release(void)
{
  gpio_release(g_cam_scl_pin);
}

static bool sccb_sda_read(void)
{
  return gpio_read_input(g_cam_sda_pin);
}

static int sccb_scl_wait_high(void)
{
  int timeout = SCCB_TIMEOUT_ITER;

  while (timeout-- > 0)
    {
      if (gpio_read_input(g_cam_scl_pin))
        {
          return 0;
        }

      up_udelay(SCCB_HALF_PERIOD_US);
    }

  syslog(LOG_ERR, "[camera] SCL stuck low — bus fault\n");
  return -ETIMEDOUT;
}

/****************************************************************************
 * Name: sccb_start
 *
 * Description:
 *   Generate SCCB START condition.  Checks bus-free first (both SDA
 *   and SCL should be high).  If bus is not free, attempts recovery.
 *   Returns 0 on success, negative errno on failure.
 *
 ****************************************************************************/

static int sccb_start(void)
{
  int ret;

  /* Release both lines first */

  sccb_sda_release();
  sccb_scl_release();
  up_udelay(SCCB_HALF_PERIOD_US);

  /* Check bus-free: both SDA and SCL should be high */

  if (!gpio_read_input(g_cam_scl_pin))
    {
      ret = sccb_scl_wait_high();
      if (ret < 0)
        {
          return ret;
        }
    }

  if (!gpio_read_input(g_cam_sda_pin))
    {
      /* SDA stuck low — try clock-stretching recovery */

      int i;
      for (i = 0; i < 9; i++)
        {
          sccb_scl_low();
          up_udelay(SCCB_HALF_PERIOD_US);
          sccb_scl_release();
          ret = sccb_scl_wait_high();
          if (ret < 0)
            {
              return ret;
            }

          up_udelay(SCCB_HALF_PERIOD_US);
          if (gpio_read_input(g_cam_sda_pin))
            {
              break;
            }
        }

      if (!gpio_read_input(g_cam_sda_pin))
        {
          syslog(LOG_ERR, "[camera] SDA stuck low — bus recovery failed\n");
          return -EIO;
        }
    }

  /* START: SDA falls while SCL is high */

  sccb_sda_low();
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_low();
  up_udelay(SCCB_HALF_PERIOD_US);

  return 0;
}

/****************************************************************************
 * Name: sccb_stop
 *
 * Description:
 *   Generate SCCB STOP condition.  Returns 0 on success,
 *   -ETIMEDOUT if SCL stays low.
 *
 ****************************************************************************/

static int sccb_stop(void)
{
  int ret;

  sccb_sda_low();
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_release();
  ret = sccb_scl_wait_high();
  if (ret < 0)
    {
      return ret;
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_sda_release();
  up_udelay(SCCB_HALF_PERIOD_US);

  return 0;
}

/****************************************************************************
 * Name: sccb_write_byte
 *
 * Description:
 *   Write one byte.  Returns 0 if ACK, -EIO on NACK, -ETIMEDOUT.
 *
 ****************************************************************************/

static int sccb_write_byte(uint8_t byte)
{
  int i;
  bool ack;
  int ret;

  for (i = 7; i >= 0; i--)
    {
      if ((byte >> i) & 1)
        {
          sccb_sda_release();
        }
      else
        {
          sccb_sda_low();
        }

      up_udelay(SCCB_HALF_PERIOD_US);

      sccb_scl_release();
      ret = sccb_scl_wait_high();
      if (ret < 0)
        {
          return ret;
        }

      up_udelay(SCCB_HALF_PERIOD_US);

      sccb_scl_low();
      up_udelay(SCCB_HALF_PERIOD_US);
    }

  /* ACK bit */

  sccb_sda_release();
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_release();
  ret = sccb_scl_wait_high();
  if (ret < 0)
    {
      return ret;
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  ack = !sccb_sda_read();

  sccb_scl_low();
  up_udelay(SCCB_HALF_PERIOD_US);

  return ack ? 0 : -EIO;
}

/****************************************************************************
 * Name: sccb_read_byte
 *
 * Description:
 *   Read one byte.  Sends ACK if ack=true, NACK if ack=false.
 *   Returns byte (0-255) on success, negative errno on failure.
 *
 ****************************************************************************/

static int sccb_read_byte(bool ack)
{
  uint8_t byte = 0;
  int i;
  int ret;

  sccb_sda_release();

  for (i = 7; i >= 0; i--)
    {
      up_udelay(SCCB_HALF_PERIOD_US);

      sccb_scl_release();
      ret = sccb_scl_wait_high();
      if (ret < 0)
        {
          return ret;
        }

      up_udelay(SCCB_HALF_PERIOD_US);

      if (sccb_sda_read())
        {
          byte |= (1u << i);
        }

      sccb_scl_low();
      up_udelay(SCCB_HALF_PERIOD_US);
    }

  /* ACK/NACK */

  if (ack)
    {
      sccb_sda_low();
    }
  else
    {
      sccb_sda_release();
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_release();
  ret = sccb_scl_wait_high();
  if (ret < 0)
    {
      return ret;
    }

  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_scl_low();
  up_udelay(SCCB_HALF_PERIOD_US);

  sccb_sda_release();

  return (int)byte;
}

/****************************************************************************
 * Name: sccb_read_reg
 *
 * Description:
 *   Read one GC2145 register via SCCB.
 *   Returns register value (0-255) on success, negative errno on error.
 *   All STOP errors are propagated to the caller.
 *
 ****************************************************************************/

static int sccb_read_reg(uint8_t reg_addr)
{
  int ret;
  int value;
  int stop_ret;

  /* Phase 1: Write register address (3-phase write) */

  ret = sccb_start();
  if (ret < 0)
    {
      return ret;
    }

  ret = sccb_write_byte((uint8_t)(GC2145_SCCB_ADDR << 1) | 0);
  if (ret < 0)
    {
      goto stop_and_fail;
    }

  ret = sccb_write_byte(reg_addr);
  if (ret < 0)
    {
      goto stop_and_fail;
    }

  stop_ret = sccb_stop();
  if (stop_ret < 0)
    {
      return stop_ret;
    }

  /* Phase 2: Read register value (2-phase read) */

  ret = sccb_start();
  if (ret < 0)
    {
      return ret;
    }

  ret = sccb_write_byte((uint8_t)(GC2145_SCCB_ADDR << 1) | 1);
  if (ret < 0)
    {
      goto stop_and_fail;
    }

  value = sccb_read_byte(false);
  if (value < 0)
    {
      ret = value;
      goto stop_and_fail;
    }

  stop_ret = sccb_stop();
  if (stop_ret < 0)
    {
      return stop_ret;
    }

  return value;

stop_and_fail:

  stop_ret = sccb_stop();
  if (stop_ret < 0)
    {
      /* STOP failed — bus is stuck; report STOP error as primary */

      return stop_ret;
    }

  return ret;
}

/****************************************************************************
 * Private Functions — MCLK
 ****************************************************************************/

/****************************************************************************
 * Name: mclk_save_state
 *
 * Description:
 *   Save ALL registers that mclk_enable will modify:
 *   - Clock source/divider (reg 0x0A)
 *   - Clock gate (reg 0x0D)
 *   - P24-P31 function select (SYS_BASE+0xCC) — read-modify-write
 *   - P27 GPIO CFG (direction/latch) — for pin-level restore
 *
 ****************************************************************************/

static void mclk_save_state(mclk_state_t *ms)
{
  ms->clk_div  = getreg32(CAMERA_CLK_DIV_REG);
  ms->clk_en   = getreg32(CAMERA_CLK_EN_REG);
  ms->func2431 = getreg32(CAMERA_GPIO_FUNC_REG);
  ms->p27_cfg  = getreg32(CAMERA_P27_CFG_REG);
  ms->valid    = true;
}

/****************************************************************************
 * Name: mclk_restore_state
 *
 * Description:
 *   Restore saved MCLK state.  Uses read-modify-write on the shared
 *   P24-P31 function register to avoid clobbering other pins.
 *   Restores P27 GPIO CFG for pin-level state.
 *   Disables clock gate last to avoid glitches.
 *
 ****************************************************************************/

static void mclk_restore_state(const mclk_state_t *ms)
{
  uint32_t val;

  if (!ms->valid)
    {
      return;
    }

  /* Restore clock source/divider (safe while gate is off) */

  putreg32(ms->clk_div, CAMERA_CLK_DIV_REG);

  /* Restore P27 function select — read-modify-write on shared register
   * to only touch P27 bits [12:15], leaving P24-P26 and P28-P31 intact.
   */

  val = getreg32(CAMERA_GPIO_FUNC_REG);
  val &= ~(CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
  val |= (ms->func2431 & (CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT));
  putreg32(val, CAMERA_GPIO_FUNC_REG);

  /* Restore P27 GPIO CFG (direction, latch, pull) */

  putreg32(ms->p27_cfg, CAMERA_P27_CFG_REG);

  /* Restore clock gate last */

  putreg32(ms->clk_en, CAMERA_CLK_EN_REG);
}

/****************************************************************************
 * Name: mclk_enable_24mhz
 *
 * Description:
 *   Configure and enable 24 MHz MCLK on P27.
 *   Uses read-modify-write on shared P24-P31 register.
 *
 ****************************************************************************/

static void mclk_enable_24mhz(void)
{
  uint32_t val;

  /* Set P27 function to CIS AUXS clock output (function 1)
   * Read-modify-write: only touch P27 bits, preserve P24-P26/P28-P31.
   */

  val = getreg32(CAMERA_GPIO_FUNC_REG);
  val &= ~(CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
  val |= (CAMERA_P27_FUNC_CIS_CLK << CAMERA_P27_FUNC_SHIFT);
  putreg32(val, CAMERA_GPIO_FUNC_REG);

  /* Set clock source and divider (read-modify-write) */

  val = getreg32(CAMERA_CLK_DIV_REG);
  val &= ~((CAMERA_CKSEL_MASK << CAMERA_CKSEL_POS) |
           (CAMERA_CKDIV_MASK << CAMERA_CKDIV_POS));
  val |= (CAMERA_CKSEL_AUXS_CIS << CAMERA_CKSEL_POS);
  val |= (CAMERA_CKDIV_24MHZ    << CAMERA_CKDIV_POS);
  putreg32(val, CAMERA_CLK_DIV_REG);

  /* Enable clock gate (read-modify-write) */

  val = getreg32(CAMERA_CLK_EN_REG);
  val |= CAMERA_CIS_AUXS_CKEN_BIT;
  putreg32(val, CAMERA_CLK_EN_REG);
}

/****************************************************************************
 * Private Functions — Power Control
 ****************************************************************************/

/****************************************************************************
 * Name: camera_power_on
 *
 * Description:
 *   Assert power-on and deassert standby.  Saves original GPIO state
 *   before modification (for restore in cleanup).
 *   Skips lines whose GPIO is -1.
 *
 ****************************************************************************/

static void camera_power_on(gpio_state_t *pwr_saved, bool *pwr_saved_ok,
                            gpio_state_t *pwdn_saved, bool *pwdn_saved_ok)
{
  if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      gpio_save_state(g_cam_pwr_pin, pwr_saved);
      *pwr_saved_ok = true;

#ifdef CONFIG_CAMERA_PWR_ACTIVE_HIGH
      gpio_set_output_high(g_cam_pwr_pin);
#else
      gpio_drive_low(g_cam_pwr_pin);
#endif

      up_udelay(5000);  /* 5 ms for power rail to stabilize */
    }

  if (g_cam_pwdn_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      gpio_save_state(g_cam_pwdn_pin, pwdn_saved);
      *pwdn_saved_ok = true;

#ifdef CONFIG_CAMERA_PWDNB_ACTIVE_HIGH
      /* ACTIVE_HIGH PWDNB: high = standby, so drive low to exit standby */

      gpio_drive_low(g_cam_pwdn_pin);
#else
      /* ACTIVE_LOW PWDNB: low = standby, so drive high to exit standby */

      gpio_set_output_high(g_cam_pwdn_pin);
#endif

      up_udelay(1000);  /* 1 ms for sensor to exit standby */
    }
}

/****************************************************************************
 * Private Functions — Reset
 ****************************************************************************/

/****************************************************************************
 * Name: camera_reset
 *
 * Description:
 *   Assert then deassert hardware reset.  Respects
 *   CONFIG_CAMERA_RST_ACTIVE_LOW polarity.
 *
 ****************************************************************************/

static void camera_reset(void)
{
#ifdef CONFIG_CAMERA_RST_ACTIVE_LOW
  /* Active-low: assert = drive low, deassert = release (high-Z) */

  gpio_drive_low(g_cam_rst_pin);
  up_udelay(10000);

  gpio_release(g_cam_rst_pin);
  up_udelay(5000);
#else
  /* Active-high: assert = drive high, deassert = drive low */

  gpio_set_output_high(g_cam_rst_pin);
  up_udelay(10000);

  gpio_drive_low(g_cam_rst_pin);
  up_udelay(5000);
#endif
}

/****************************************************************************
 * Private Functions — Config Validation
 ****************************************************************************/

/****************************************************************************
 * Name: camera_check_config
 *
 * Description:
 *   Three-stage configuration validation:
 *   Stage 1: Check 9 confirmed sentinels
 *   Stage 2: Validate GPIO pin values (range, uniqueness)
 *   Stage 3: Check conflicts with UART/SWD/LCD
 *   Stage 4: MCLK-specific: enforce GPIO == 27 when confirmed
 *
 ****************************************************************************/

static int camera_check_config(void)
{
  bool ok = true;

#ifdef CONFIG_CAMERA_SCCB_CONFIRMED
  const char *sccb_st = "y";
#else
  const char *sccb_st = "n";
#endif

#ifdef CONFIG_CAMERA_SDA_SCL_ROLE_CONFIRMED
  const char *role_st = "y";
#else
  const char *role_st = "n";
#endif

#ifdef CONFIG_CAMERA_RST_GPIO_CONFIRMED
  const char *rst_gpio_st = "y";
#else
  const char *rst_gpio_st = "n";
#endif

#ifdef CONFIG_CAMERA_RST_POLARITY_CONFIRMED
  const char *rst_pol_st = "y";
#else
  const char *rst_pol_st = "n";
#endif

#ifdef CONFIG_CAMERA_PWR_CONFIRMED
  const char *pwr_st = "y";
#else
  const char *pwr_st = "n";
#endif

#ifdef CONFIG_CAMERA_PWR_POLARITY_CONFIRMED
  const char *pwr_pol_st = "y";
#else
  const char *pwr_pol_st = "n";
#endif

#ifdef CONFIG_CAMERA_PWDNB_CONFIRMED
  const char *pwdnb_st = "y";
#else
  const char *pwdnb_st = "n";
#endif

#ifdef CONFIG_CAMERA_PWDNB_POLARITY_CONFIRMED
  const char *pwdnb_pol_st = "y";
#else
  const char *pwdnb_pol_st = "n";
#endif

#ifdef CONFIG_CAMERA_MCLK_CONFIRMED
  const char *mclk_st = "y";
#else
  const char *mclk_st = "n";
#endif

  syslog(LOG_INFO,
         "[camera] Board config:\n"
         "  SCCB_SDA  = %d  (net=%s role=%s)\n"
         "  SCCB_SCL  = %d  (net=%s role=%s)\n"
         "  DVP_RST   = %d  (gpio=%s pol=%s)\n"
         "  PWR_CTL   = %d  (net=%s pol=%s)\n"
         "  PWDNB     = %d  (net=%s pol=%s)\n"
         "  MCLK      = %d  (confirmed=%s)\n",
         g_cam_sda_pin, sccb_st, role_st,
         g_cam_scl_pin, sccb_st, role_st,
         g_cam_rst_pin, rst_gpio_st, rst_pol_st,
         g_cam_pwr_pin, pwr_st, pwr_pol_st,
         g_cam_pwdn_pin, pwdnb_st, pwdnb_pol_st,
         g_cam_mclk_pin, mclk_st);

  /* ---- Stage 1: confirmed sentinel checks ---- */

#ifndef CONFIG_CAMERA_SCCB_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: SCCB network NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_SCCB_CONFIRMED=y after verifying\n"
         "[camera]   SCL/SDA net exists on the product board.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_SDA_SCL_ROLE_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: SDA/SCL role NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_SDA_SCL_ROLE_CONFIRMED=y after\n"
         "[camera]   verifying which GPIO is SDA and which is SCL.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_RST_GPIO_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: DVP_RST GPIO NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_RST_GPIO_CONFIRMED=y after\n"
         "[camera]   verifying DVP_RST net on the schematic.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_RST_POLARITY_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: DVP_RST polarity NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_RST_POLARITY_CONFIRMED=y after\n"
         "[camera]   verifying active-low vs active-high.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_PWR_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: DVP_PWR_CTL network NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_PWR_CONFIRMED=y after verifying.\n"
         "[camera]   Use GPIO=-1 + confirmed=y if power is always-on.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_PWR_POLARITY_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: PWR_CTL polarity NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_PWR_POLARITY_CONFIRMED=y after\n"
         "[camera]   verifying active-high vs active-low.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_PWDNB_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: PWDNB network NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_PWDNB_CONFIRMED=y after verifying.\n"
         "[camera]   Use GPIO=-1 + confirmed=y if hard-wired.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_PWDNB_POLARITY_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: PWDNB polarity NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_PWDNB_POLARITY_CONFIRMED=y after\n"
         "[camera]   verifying active-high vs active-low.\n");
  ok = false;
#endif

#ifndef CONFIG_CAMERA_MCLK_CONFIRMED
  syslog(LOG_ERR,
         "[camera] BLOCKER: MCLK NOT confirmed\n"
         "[camera]   Set CONFIG_CAMERA_MCLK_CONFIRMED=y only after:\n"
         "[camera]     - P27 verified as MCLK output on this board\n"
         "[camera]     - cksel=3 source confirmed as 480 MHz PLL\n"
         "[camera]     - divider semantics (ckdiv+1) confirmed\n"
         "[camera]     - no /2 pre-divider ambiguity remains\n");
  ok = false;
#endif

  if (!ok)
    {
      syslog(LOG_ERR,
             "[camera] ======== HARD BLOCKER(S) PRESENT ========\n"
             "[camera] No MMIO was accessed.  No GPIOs were modified.\n"
             "[camera] Fix all blockers above, then re-run.\n");
      return -ENOTSUP;
    }

  /* ---- Stage 2: GPIO pin value validation ---- */

  if (!gpio_is_valid(g_cam_sda_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: SCCB SDA pin %d out of range (%d-%d)\n",
             g_cam_sda_pin, CAMERA_GPIO_MIN, CAMERA_GPIO_MAX);
      ok = false;
    }

  if (!gpio_is_valid(g_cam_scl_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: SCCB SCL pin %d out of range (%d-%d)\n",
             g_cam_scl_pin, CAMERA_GPIO_MIN, CAMERA_GPIO_MAX);
      ok = false;
    }

  if (gpio_is_valid(g_cam_sda_pin) && gpio_is_valid(g_cam_scl_pin) &&
      g_cam_sda_pin == g_cam_scl_pin)
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: SDA and SCL are the same pin (%d)\n",
             g_cam_sda_pin);
      ok = false;
    }

  if (g_cam_rst_pin != CAMERA_GPIO_UNCONFIGURED &&
      !gpio_is_valid(g_cam_rst_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: DVP_RST pin %d out of range\n",
             g_cam_rst_pin);
      ok = false;
    }

  if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED &&
      !gpio_is_valid(g_cam_pwr_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: PWR_CTL pin %d out of range\n",
             g_cam_pwr_pin);
      ok = false;
    }

  if (g_cam_pwdn_pin != CAMERA_GPIO_UNCONFIGURED &&
      !gpio_is_valid(g_cam_pwdn_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: PWDNB pin %d out of range\n",
             g_cam_pwdn_pin);
      ok = false;
    }

  if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED &&
      !gpio_is_valid(g_cam_mclk_pin))
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: MCLK pin %d out of range\n",
             g_cam_mclk_pin);
      ok = false;
    }

  /* GPIO uniqueness (no pin sharing) */

  {
    int pins[6];
    int n = 0;
    int i, j;

    if (gpio_is_valid(g_cam_sda_pin))  pins[n++] = g_cam_sda_pin;
    if (gpio_is_valid(g_cam_scl_pin))  pins[n++] = g_cam_scl_pin;
    if (g_cam_rst_pin != CAMERA_GPIO_UNCONFIGURED &&
        gpio_is_valid(g_cam_rst_pin))  pins[n++] = g_cam_rst_pin;
    if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED &&
        gpio_is_valid(g_cam_pwr_pin))  pins[n++] = g_cam_pwr_pin;
    if (g_cam_pwdn_pin != CAMERA_GPIO_UNCONFIGURED &&
        gpio_is_valid(g_cam_pwdn_pin)) pins[n++] = g_cam_pwdn_pin;
    if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED &&
        gpio_is_valid(g_cam_mclk_pin)) pins[n++] = g_cam_mclk_pin;

    for (i = 0; i < n; i++)
      {
        for (j = i + 1; j < n; j++)
          {
            if (pins[i] == pins[j])
              {
                syslog(LOG_ERR,
                       "[camera] BLOCKER: GPIO %d assigned to "
                       "multiple roles\n", pins[i]);
                ok = false;
              }
          }
      }
  }

  /* ---- Stage 3: Conflict with board-level reserved pins ---- */

  {
    static const struct { int pin; const char *name; } reserved[] =
      {
        { CAMERA_PIN_UART0_RX, "UART0 RX" },
        { CAMERA_PIN_UART0_TX, "UART0 TX" },
        { CAMERA_PIN_SWD_CLK,  "SWD CLK"  },
        { CAMERA_PIN_SWD_IO,   "SWD IO"   },
      };

    int i, r;

    static const int cam_pins[] =
      {
        CONFIG_CAMERA_GPIO_SDA,
        CONFIG_CAMERA_GPIO_SCL,
        CONFIG_CAMERA_GPIO_RST,
        CONFIG_CAMERA_GPIO_PWR_CTL,
        CONFIG_CAMERA_GPIO_PWDNB,
        CONFIG_CAMERA_MCLK_GPIO,
      };

    for (i = 0; i < 6; i++)
      {
        if (cam_pins[i] == CAMERA_GPIO_UNCONFIGURED)
          {
            continue;
          }

        for (r = 0; r < 4; r++)
          {
            if (cam_pins[i] == reserved[r].pin)
              {
                syslog(LOG_ERR,
                       "[camera] BLOCKER: camera pin %d conflicts "
                       "with %s\n", cam_pins[i], reserved[r].name);
                ok = false;
              }
          }
      }
  }

  /* ---- Stage 4: MCLK-specific enforcement ---- */

#ifdef CONFIG_CAMERA_MCLK_CONFIRMED
  if (g_cam_mclk_pin != CAMERA_MCLK_REQUIRED_PIN)
    {
      syslog(LOG_ERR,
             "[camera] BLOCKER: MCLK_GPIO=%d but implementation "
             "requires %d (P27)\n",
             g_cam_mclk_pin, CAMERA_MCLK_REQUIRED_PIN);
      ok = false;
    }
#endif

  if (!ok)
    {
      syslog(LOG_ERR,
             "[camera] Cannot proceed — fix blockers above.\n"
             "[camera] No MMIO was accessed.  No GPIOs were modified.\n");
      return -ENODEV;
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_camera_id
 *
 * Description:
 *   Phase 0 "camera id" command.  Reads GC2145 registers 0xF0/0xF1
 *   via SCCB bit-bang.  All GPIO states are saved before use and
 *   restored on cleanup.
 *
 ****************************************************************************/

int bk7258_camera_id(void)
{
  gpio_state_t sda_saved;
  gpio_state_t scl_saved;
  gpio_state_t rst_saved;
  gpio_state_t pwr_saved;
  gpio_state_t pwdn_saved;
  mclk_state_t mclk_saved = { .valid = false };
  int id_h = -1;
  int id_l = -1;
  uint16_t chip_id;
  int ret;
  int stop_ret;
  bool sda_saved_ok = false;
  bool scl_saved_ok = false;
  bool rst_saved_ok = false;
  bool pwr_saved_ok = false;
  bool pwdn_saved_ok = false;
  bool mclk_on = false;

  /* ================================================================
   * Config validation — NO MMIO before this point.
   * ================================================================ */

  ret = camera_check_config();
  if (ret < 0)
    {
      return ret;
    }

  syslog(LOG_INFO,
         "[camera] Config OK — proceeding with SCCB ID read\n");

  /* ================================================================
   * GPIO setup: save pinmux, configure for SCCB/power/reset.
   * From this point onward we touch hardware.
   * ================================================================ */

  gpio_save_state(g_cam_sda_pin, &sda_saved);
  sda_saved_ok = true;

  gpio_save_state(g_cam_scl_pin, &scl_saved);
  scl_saved_ok = true;

  gpio_release(g_cam_sda_pin);
  gpio_release(g_cam_scl_pin);
  up_udelay(100);

  if (g_cam_rst_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      gpio_save_state(g_cam_rst_pin, &rst_saved);
      rst_saved_ok = true;
    }

  /* Power on (saves PWR/PWDNB states internally) */

  camera_power_on(&pwr_saved, &pwr_saved_ok,
                  &pwdn_saved, &pwdn_saved_ok);

  /* MCLK (saves P27 CFG + clock regs) */

  if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED)
    {
      mclk_save_state(&mclk_saved);
      mclk_enable_24mhz();
      mclk_on = true;
      up_udelay(500);
    }

  /* Hardware reset */

  if (rst_saved_ok)
    {
      camera_reset();
    }

  /* ================================================================
   * SCCB ID read
   * ================================================================ */

  id_h = sccb_read_reg(GC2145_REG_ID_H);
  if (id_h < 0)
    {
      syslog(LOG_ERR,
             "[camera] Failed to read ID high byte: %d\n", id_h);
      ret = id_h;
      goto cleanup;
    }

  id_l = sccb_read_reg(GC2145_REG_ID_L);
  if (id_l < 0)
    {
      syslog(LOG_ERR,
             "[camera] Failed to read ID low byte: %d\n", id_l);
      ret = id_l;
      goto cleanup;
    }

  chip_id = (uint16_t)((id_h << 8) | id_l);

  syslog(LOG_INFO,
         "[camera] GC2145 chip ID: 0x%04X "
         "(reg 0xF0=0x%02X, reg 0xF1=0x%02X)\n",
         chip_id, (uint8_t)id_h, (uint8_t)id_l);

  if (chip_id == 0x2145)
    {
      syslog(LOG_INFO,
             "[camera] ID match: GC2145 confirmed.\n");
      ret = 0;
    }
  else
    {
      syslog(LOG_ERR,
             "[camera] ID mismatch: expected 0x2145, got 0x%04X\n",
             chip_id);
      ret = -ENODEV;
    }

cleanup:

  /* ================================================================
   * Cleanup: restore ALL GPIO states.  Order:
   *   1. SCCB stop (best-effort)
   *   2. MCLK restore (clock regs + P27 CFG + pinmux)
   *   3. RST restore
   *   4. PWDNB restore
   *   5. PWR restore
   *   6. SCL restore
   *   7. SDA restore
   * ================================================================ */

  stop_ret = sccb_stop();

  if (mclk_on)
    {
      mclk_restore_state(&mclk_saved);
    }

  if (rst_saved_ok)
    {
      gpio_restore_state(&rst_saved);
    }

  if (pwdn_saved_ok)
    {
      gpio_restore_state(&pwdn_saved);
    }

  if (pwr_saved_ok)
    {
      gpio_restore_state(&pwr_saved);
    }

  if (scl_saved_ok)
    {
      gpio_restore_state(&scl_saved);
    }

  if (sda_saved_ok)
    {
      gpio_restore_state(&sda_saved);
    }

  syslog(LOG_INFO,
         "[camera] GPIO cleanup complete — all pins restored.\n");

  /* Merge STOP error into return value: if the SCCB transaction
   * succeeded (ret == 0) but STOP failed, report the STOP error.
   */

  if (ret == 0 && stop_ret < 0)
    {
      ret = stop_ret;
    }

  return ret;
}

