141	/****************************************************************************
142	 * GPIO Helpers
143	 *
144	 * register: CFG = AON_GPIO_BASE + pin*4
145	 *   bit[1] = output value (0=low, 1=high)
146	 *   bit[3] = output enable (active-low: 0=enabled)
147	 *   bit[2] = input enable
148	 *   bit[6] = second function
149	 ****************************************************************************/
150	
151	static inline bool gpio_is_valid(int pin)
152	{
153	  return pin >= CAMERA_GPIO_MIN && pin <= CAMERA_GPIO_MAX;
154	}
155	
156	static void gpio_save_state(int pin, gpio_state_t *s)
157	{
158	  int shift;
159	  uint32_t func_raw;
160	
161	  s->pin       = pin;
162	  s->cfg_addr  = BK7258_GPIO_CFG(pin);
163	  s->func_addr = BK7258_SYS_GPIO_FUNC(pin);
164	  s->cfg       = getreg32(s->cfg_addr);
165	
166	  /* Save only this pin's 4-bit function field */
167	
168	  func_raw = getreg32(s->func_addr);
169	  shift    = (pin & 7) * 4;
170	  s->func  = (func_raw >> shift) & 0xFu;
171	}
172	
173	static void gpio_restore_state(const gpio_state_t *s)
174	{
175	  int shift;
176	  uint32_t func_val;
177	
178	  putreg32(s->cfg, s->cfg_addr);
179	
180	  /* Read-modify-write: only restore this pin's 4-bit function field */
181	
182	  shift    = (s->pin & 7) * 4;
183	  func_val = getreg32(s->func_addr);
184	  func_val &= ~(0xFu << shift);
185	  func_val |= (s->func & 0xFu) << shift;
186	  putreg32(func_val, s->func_addr);
187	}
188	
189	/****************************************************************************
190	 * Name: gpio_drive_low
191	 *   Output value=0, output enabled, GPIO mode.
192	 ****************************************************************************/
193	
194	static void gpio_drive_low(int pin)
195	{
196	  uintptr_t addr = BK7258_GPIO_CFG(pin);
197	  uint32_t cfg = getreg32(addr);
198	
199	  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* bit6=0: GPIO mode */
200	  cfg &= ~GPIO_CFG_OUTPUT;       /* bit1=0: output value = LOW */
201	  cfg &= ~GPIO_CFG_OUTPUT_EN;    /* bit3=0: output enabled (active-low) */
202	
203	  putreg32(cfg, addr);
204	}
205	
206	/****************************************************************************
207	 * Name: gpio_set_output_high
208	 *   Output value=1, output enabled, GPIO mode.
209	 ****************************************************************************/
210	
211	static void gpio_set_output_high(int pin)
212	{
213	  uintptr_t addr = BK7258_GPIO_CFG(pin);
214	  uint32_t cfg = getreg32(addr);
215	
216	  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* bit6=0: GPIO mode */
217	  cfg |=  GPIO_CFG_OUTPUT;       /* bit1=1: output value = HIGH */
218	  cfg &= ~GPIO_CFG_OUTPUT_EN;    /* bit3=0: output enabled (active-low) */
219	
220	  putreg32(cfg, addr);
221	}
222	
223	/****************************************************************************
224	 * Name: gpio_release
225	 *   Output disabled, input enabled, GPIO mode (high-Z).
226	 ****************************************************************************/
227	
228	static void gpio_release(int pin)
229	{
230	  uintptr_t addr = BK7258_GPIO_CFG(pin);
231	  uint32_t cfg = getreg32(addr);
232	
233	  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* bit6=0: GPIO mode */
234	  cfg &= ~GPIO_CFG_OUTPUT;       /* bit1=0: value=0 (irrelevant when out dis) */
235	  cfg |=  GPIO_CFG_OUTPUT_EN;    /* bit3=1: output DISABLED (active-low) */
236	  cfg |=  GPIO_CFG_INPUT_EN;     /* bit2=1: input enabled */
237	
238	  putreg32(cfg, addr);
239	}
240	
241	static bool gpio_read_input(int pin)
242	{
243	  return (getreg32(BK7258_GPIO_CFG(pin)) & GPIO_CFG_INPUT) != 0;
244	}
245	
246	/****************************************************************************
247	 * SCCB Bit-Bang
248	 ****************************************************************************/
249

250	static void sccb_sda_low(void)     { gpio_drive_low(g_cam_sda_pin); }
251	static void sccb_sda_release(void) { gpio_release(g_cam_sda_pin); }
252	static void sccb_scl_low(void)     { gpio_drive_low(g_cam_scl_pin); }
253	static void sccb_scl_release(void) { gpio_release(g_cam_scl_pin); }
254	static bool sccb_sda_read(void)    { return gpio_read_input(g_cam_sda_pin); }
255	
256	static int sccb_scl_wait_high(void)
257	{
258	  int timeout = SCCB_TIMEOUT_ITER;
259	  while (timeout-- > 0)
260	    {
261	      if (gpio_read_input(g_cam_scl_pin)) return 0;
262	      up_udelay(SCCB_HALF_PERIOD_US);
263	    }
264	  syslog(LOG_ERR, "[camera] SCL stuck low\n");
265	  return -ETIMEDOUT;
266	}
267	
268	static int sccb_start(void)
269	{
270	  int ret;
271	
272	  sccb_sda_release();
273	  sccb_scl_release();
274	  up_udelay(SCCB_HALF_PERIOD_US);
275	
276	  /* Bus-free check */
277	
278	  if (!gpio_read_input(g_cam_scl_pin))
279	    {
280	      ret = sccb_scl_wait_high();
281	      if (ret < 0) return ret;
282	    }
283	
284	  if (!gpio_read_input(g_cam_sda_pin))
285	    {
286	      /* SDA stuck low — 9-clock recovery */
287	
288	      int i;
289	      for (i = 0; i < 9; i++)
290	        {
291	          sccb_scl_low();
292	          up_udelay(SCCB_HALF_PERIOD_US);
293	          sccb_scl_release();
294	          ret = sccb_scl_wait_high();
295	          if (ret < 0) return ret;
296	          up_udelay(SCCB_HALF_PERIOD_US);
297	          if (gpio_read_input(g_cam_sda_pin)) break;
298	        }
299	      if (!gpio_read_input(g_cam_sda_pin))
300	        {
301	          syslog(LOG_ERR, "[camera] SDA stuck low — recovery failed\n");
302	          return -EIO;
303	        }
304	    }
305	
306	  /* START: SDA falls while SCL high */
307	
308	  sccb_sda_low();
309	  up_udelay(SCCB_HALF_PERIOD_US);
310	  sccb_scl_low();
311	  up_udelay(SCCB_HALF_PERIOD_US);
312	
313	  return 0;
314	}
315	
316	static int sccb_stop(void)
317	{
318	  int ret;
319	
320	  sccb_sda_low();
321	  up_udelay(SCCB_HALF_PERIOD_US);
322	
323	  sccb_scl_release();
324	  ret = sccb_scl_wait_high();
325	  if (ret < 0) return ret;
326	
327	  up_udelay(SCCB_HALF_PERIOD_US);
328	
329	  sccb_sda_release();
330	  up_udelay(SCCB_HALF_PERIOD_US);
331	
332	  return 0;
333	}
334	
335	static int sccb_write_byte(uint8_t byte)
336	{
337	  int i, ret;
338	  bool ack;
339	
340	  for (i = 7; i >= 0; i--)
341	    {
342	      if ((byte >> i) & 1) sccb_sda_release();
343	      else                 sccb_sda_low();
344	
345	      up_udelay(SCCB_HALF_PERIOD_US);
346	
347	      sccb_scl_release();
348	      ret = sccb_scl_wait_high();
349	      if (ret < 0) return ret;
350	      up_udelay(SCCB_HALF_PERIOD_US);
351	
352	      sccb_scl_low();
353	      up_udelay(SCCB_HALF_PERIOD_US);
354	    }
355	
356	  /* ACK clock */
357	
358	  sccb_sda_release();
359	  up_udelay(SCCB_HALF_PERIOD_US);
360	
361	  sccb_scl_release();
362	  ret = sccb_scl_wait_high();
363	  if (ret < 0) return ret;
364	  up_udelay(SCCB_HALF_PERIOD_US);
365	
366	  ack = !sccb_sda_read();
367	
368	  sccb_scl_low();
369	  up_udelay(SCCB_HALF_PERIOD_US);
370	
371	  return ack ? 0 : -EIO;
372	}
373	
374	static int sccb_read_byte(bool ack)
375	{
376	  uint8_t byte = 0;
377	  int i, ret;
378	
379	  sccb_sda_release();
380	
381	  for (i = 7; i >= 0; i--)
382	    {
383	      up_udelay(SCCB_HALF_PERIOD_US);
384	      sccb_scl_release();
385	      ret = sccb_scl_wait_high();
386	      if (ret < 0) return ret;
387	      up_udelay(SCCB_HALF_PERIOD_US);
388	
389	      if (sccb_sda_read()) byte |= (1u << i);
390	
391	      sccb_scl_low();
392	      up_udelay(SCCB_HALF_PERIOD_US);
393	    }
394	
395	  if (ack) sccb_sda_low();
396	  else     sccb_sda_release();
397	
398	  up_udelay(SCCB_HALF_PERIOD_US);
399	
400	  sccb_scl_release();
401	  ret = sccb_scl_wait_high();
402	  if (ret < 0) return ret;
403	  up_udelay(SCCB_HALF_PERIOD_US);
404	
405	  sccb_scl_low();
406	  up_udelay(SCCB_HALF_PERIOD_US);
407	  sccb_sda_release();
408	
409	  return (int)byte;
410	}
411	
412	static int sccb_read_reg(uint8_t reg_addr)
413	{
414	  int ret, value, stop_ret;
415	
416	  /* Phase 1: write address */
417	
418	  ret = sccb_start();
419	  if (ret < 0) return ret;
420	
421	  ret = sccb_write_byte((uint8_t)(GC2145_SCCB_ADDR << 1) | 0);
422	  if (ret < 0) goto stop_fail;
423	
424	  ret = sccb_write_byte(reg_addr);
425	  if (ret < 0) goto stop_fail;
426	
427	  stop_ret = sccb_stop();
428	  if (stop_ret < 0) return stop_ret;
429	
430	  /* Phase 2: read value */
431	
432	  ret = sccb_start();
433	  if (ret < 0) return ret;
434	
435	  ret = sccb_write_byte((uint8_t)(GC2145_SCCB_ADDR << 1) | 1);
436	  if (ret < 0) goto stop_fail;
437	
438	  value = sccb_read_byte(false);
439	  if (value < 0) { ret = value; goto stop_fail; }
440	
441	  stop_ret = sccb_stop();
442	  if (stop_ret < 0) return stop_ret;
443	
444	  return value;
445	
446	stop_fail:
447	  stop_ret = sccb_stop();
448	  return (stop_ret < 0) ? stop_ret : ret;
449	}

