451	/****************************************************************************
452	 * MCLK
453	 *
454	 * mclk_enable_24mhz modifies 4 registers:
455	 *   1. GPIO FUNC (shared P24-P31) — only P27 bits
456	 *   2. P27 GPIO CFG — set second_func=1 (bit6)
457	 *   3. CLK DIV — cksel + ckdiv
458	 *   4. CLK EN — enable gate
459	 *
460	 * Restore uses read-modify-write on shared registers.
461	 ****************************************************************************/
462	
463	static void mclk_save_state(mclk_state_t *ms)
464	{
465	  uint32_t val;
466	
467	  /* Save only the MCLK-relevant bit fields from shared registers */
468	
469	  val = getreg32(CAMERA_CLK_DIV_REG);
470	  ms->clk_div = val & ((CAMERA_CKSEL_MASK << CAMERA_CKSEL_POS) |
471	                        (CAMERA_CKDIV_MASK << CAMERA_CKDIV_POS));
472	
473	  val = getreg32(CAMERA_CLK_EN_REG);
474	  ms->clk_en = val & CAMERA_CIS_AUXS_CKEN_BIT;
475	
476	  val = getreg32(CAMERA_GPIO_FUNC_REG);
477	  ms->func2431 = val & (CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
478	
479	  ms->p27_cfg = getreg32(BK7258_GPIO_CFG(CAMERA_MCLK_REQUIRED_PIN));
480	  ms->valid   = true;
481	}
482	
483	static void mclk_restore_state(const mclk_state_t *ms)
484	{
485	  uint32_t val;
486	
487	  if (!ms->valid) return;
488	
489	  /* 1. Gate OFF first — avoid glitch while source/divider changes */
490	
491	  val = getreg32(CAMERA_CLK_EN_REG);
492	  val &= ~CAMERA_CIS_AUXS_CKEN_BIT;
493	  putreg32(val, CAMERA_CLK_EN_REG);
494	
495	  /* 2. Restore cksel/ckdiv — read-modify-write, safe while gate off */
496	
497	  val = getreg32(CAMERA_CLK_DIV_REG);
498	  val &= ~((CAMERA_CKSEL_MASK << CAMERA_CKSEL_POS) |
499	            (CAMERA_CKDIV_MASK << CAMERA_CKDIV_POS));
500	  val |= ms->clk_div;
501	  putreg32(val, CAMERA_CLK_DIV_REG);
502	
503	  /* 3. Restore P27 function select — read-modify-write FUNC reg */
504	
505	  val = getreg32(CAMERA_GPIO_FUNC_REG);
506	  val &= ~(CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
507	  val |= ms->func2431;
508	  putreg32(val, CAMERA_GPIO_FUNC_REG);
509	
510	  /* 4. Restore P27 GPIO CFG (direction/latch/pull) — per-pin, safe */
511	
512	  putreg32(ms->p27_cfg, BK7258_GPIO_CFG(CAMERA_MCLK_REQUIRED_PIN));
513	
514	  /* 5. Restore saved gate state — read-modify-write CLK_EN */
515	
516	  val = getreg32(CAMERA_CLK_EN_REG);
517	  val &= ~CAMERA_CIS_AUXS_CKEN_BIT;
518	  val |= ms->clk_en;
519	  putreg32(val, CAMERA_CLK_EN_REG);
520	}
521	
522	static void mclk_enable_24mhz(void)
523	{
524	  uint32_t val;
525	
526	  /* 1. Gate OFF — avoid glitch while source/divider changes */
527	
528	  val = getreg32(CAMERA_CLK_EN_REG);
529	  val &= ~CAMERA_CIS_AUXS_CKEN_BIT;
530	  putreg32(val, CAMERA_CLK_EN_REG);
531	
532	  /* 2. Unmap P27 — clear function select (ARMino: gpio_dev_unmap) */
533	
534	  val = getreg32(CAMERA_GPIO_FUNC_REG);
535	  val &= ~(CAMERA_P27_FUNC_MASK << CAMERA_P27_FUNC_SHIFT);
536	  putreg32(val, CAMERA_GPIO_FUNC_REG);
537	
538	  /* 3. Remap P27 → CIS AUXS clock (ARMino: gpio_dev_map) */
539	
540	  val = getreg32(CAMERA_GPIO_FUNC_REG);
541	  val |= (CAMERA_P27_FUNC_CIS_CLK << CAMERA_P27_FUNC_SHIFT);
542	  putreg32(val, CAMERA_GPIO_FUNC_REG);
543	
544	  /* 4. Prep P27 GPIO: disable output/input/pull before switching function
545	   *    (ARMino: gpio_hal_func_map → gpio_hal_set_pull/ output_dis / input_dis)
546	   *    Saved in mclk_save_state(), restored in mclk_restore_state().
547	   */
548	
549	  val = getreg32(BK7258_GPIO_CFG(CAMERA_MCLK_REQUIRED_PIN));
550	  val |=  GPIO_CFG_OUTPUT_EN;    /* bit3=1: output DISABLED (active-low) */
551	  val &= ~GPIO_CFG_INPUT_EN;     /* bit2=0: input disabled */
552	  val &= ~GPIO_CFG_PULL_EN;      /* bit5=0: pull disabled */
553	  val |=  GPIO_CFG_SECOND_FUNC;  /* bit6=1: peripheral function */
554	  putreg32(val, BK7258_GPIO_CFG(CAMERA_MCLK_REQUIRED_PIN));
555	
556	  /* 5. Set clock source and divider — read-modify-write
557	   *    (ARMino: sys_drv_set_auxs_cis(3, 19))
558	   */
559	
560	  val = getreg32(CAMERA_CLK_DIV_REG);
561	  val &= ~((CAMERA_CKSEL_MASK << CAMERA_CKSEL_POS) |
562	           (CAMERA_CKDIV_MASK << CAMERA_CKDIV_POS));
563	  val |= (CAMERA_CKSEL_AUXS_CIS << CAMERA_CKSEL_POS);
564	  val |= (CAMERA_CKDIV_24MHZ    << CAMERA_CKDIV_POS);
565	  putreg32(val, CAMERA_CLK_DIV_REG);
566	
567	  /* 6. Enable clock gate — read-modify-write
568	   *    (ARMino: sys_drv_set_cis_auxs_clk_en(1))
569	   */
570	
571	  val = getreg32(CAMERA_CLK_EN_REG);
572	  val |= CAMERA_CIS_AUXS_CKEN_BIT;
573	  putreg32(val, CAMERA_CLK_EN_REG);
574	}
