576	/****************************************************************************
577	 * Power Control
578	 ****************************************************************************/
579	
580	static void camera_power_on(gpio_state_t *pwr_saved, bool *pwr_ok,
581	                            gpio_state_t *pwdn_saved, bool *pwdn_ok)
582	{
583	  if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED)
584	    {
585	      gpio_save_state(g_cam_pwr_pin, pwr_saved);
586	      *pwr_ok = true;
587	
588	#ifdef CONFIG_CAMERA_PWR_ACTIVE_HIGH
589	      gpio_set_output_high(g_cam_pwr_pin);
590	#else
591	      gpio_drive_low(g_cam_pwr_pin);
592	#endif
593	      up_udelay(5000);
594	    }
595	
596	  if (g_cam_pwdn_pin != CAMERA_GPIO_UNCONFIGURED)
597	    {
598	      gpio_save_state(g_cam_pwdn_pin, pwdn_saved);
599	      *pwdn_ok = true;
600	
601	#ifdef CONFIG_CAMERA_PWDNB_ACTIVE_HIGH
602	      /* high=standby → drive LOW to exit standby */
603	
604	      gpio_drive_low(g_cam_pwdn_pin);
605	#else
606	      /* low=standby → drive HIGH to exit standby */
607	
608	      gpio_set_output_high(g_cam_pwdn_pin);
609	#endif
610	      up_udelay(1000);
611	    }
612	}
