634	 * Config Validation
635	 ****************************************************************************/
636	
637	static int camera_check_config(void)
638	{
639	  bool ok = true;
640	
641	#ifdef CONFIG_CAMERA_SCCB_CONFIRMED
642	  const char *sccb_st = "y";
643	#else
644	  const char *sccb_st = "n";
645	#endif
646	#ifdef CONFIG_CAMERA_SDA_SCL_ROLE_CONFIRMED
647	  const char *role_st = "y";
648	#else
649	  const char *role_st = "n";

650	#endif
651	#ifdef CONFIG_CAMERA_RST_GPIO_CONFIRMED
652	  const char *rst_g_st = "y";
653	#else
654	  const char *rst_g_st = "n";
655	#endif
656	#ifdef CONFIG_CAMERA_RST_POLARITY_CONFIRMED
657	  const char *rst_p_st = "y";
658	#else
659	  const char *rst_p_st = "n";
660	#endif
661	#ifdef CONFIG_CAMERA_PWR_CONFIRMED
662	  const char *pwr_st = "y";
663	#else
664	  const char *pwr_st = "n";
665	#endif
666	#ifdef CONFIG_CAMERA_PWR_POLARITY_CONFIRMED
667	  const char *pwr_p_st = "y";
668	#else
669	  const char *pwr_p_st = "n";
670	#endif
671	#ifdef CONFIG_CAMERA_MCLK_CONFIRMED
672	  const char *mclk_st = "y";
673	#else
674	  const char *mclk_st = "n";
675	#endif
676	
677	  syslog(LOG_INFO,
678	         "[camera] Config: SDA=%d(net=%s role=%s) SCL=%d "
679	         "RST=%d(gpio=%s pol=%s) PWR=%d(net=%s pol=%s) "
680	         "MCLK=%d(conf=%s)\n",
681	         g_cam_sda_pin, sccb_st, role_st,
682	         g_cam_scl_pin,
683	         g_cam_rst_pin, rst_g_st, rst_p_st,
684	         g_cam_pwr_pin, pwr_st, pwr_p_st,
685	         g_cam_mclk_pin, mclk_st);
686	
687	  /* Stage 1: 7 confirmed sentinels */
688	
689	#ifndef CONFIG_CAMERA_SCCB_CONFIRMED
690	  syslog(LOG_ERR, "[camera] BLOCKER: SCCB net NOT confirmed\n"); ok = false;
691	#endif
692	#ifndef CONFIG_CAMERA_SDA_SCL_ROLE_CONFIRMED
693	  syslog(LOG_ERR, "[camera] BLOCKER: SDA/SCL role NOT confirmed\n"); ok = false;
694	#endif
695	#ifndef CONFIG_CAMERA_RST_GPIO_CONFIRMED
696	  syslog(LOG_ERR, "[camera] BLOCKER: RST GPIO NOT confirmed\n"); ok = false;
697	#endif
698	#ifndef CONFIG_CAMERA_RST_POLARITY_CONFIRMED
699	  syslog(LOG_ERR, "[camera] BLOCKER: RST polarity NOT confirmed\n"); ok = false;
700	#endif
701	#ifndef CONFIG_CAMERA_PWR_CONFIRMED
702	  syslog(LOG_ERR, "[camera] BLOCKER: PWR net NOT confirmed\n"); ok = false;
703	#endif
704	#ifndef CONFIG_CAMERA_PWR_POLARITY_CONFIRMED
705	  syslog(LOG_ERR, "[camera] BLOCKER: PWR polarity NOT confirmed\n"); ok = false;
706	#endif
707	#ifndef CONFIG_CAMERA_MCLK_CONFIRMED
708	  syslog(LOG_ERR, "[camera] BLOCKER: MCLK NOT confirmed\n"); ok = false;
709	#endif
710	
711	  if (!ok)
712	    {
713	      syslog(LOG_ERR,
714	             "[camera] ======== 7 BLOCKERS — no MMIO touched ========\n");
715	      return -ENOTSUP;
716	    }
717	
718	  /* Stage 2: GPIO range + uniqueness */
719	
720	  if (!gpio_is_valid(g_cam_sda_pin))
721	    { syslog(LOG_ERR, "[camera] SDA pin %d out of range\n", g_cam_sda_pin);
722	      ok = false; }
723	  if (!gpio_is_valid(g_cam_scl_pin))
724	    { syslog(LOG_ERR, "[camera] SCL pin %d out of range\n", g_cam_scl_pin);
725	      ok = false; }
726	  if (gpio_is_valid(g_cam_sda_pin) && gpio_is_valid(g_cam_scl_pin) &&
727	      g_cam_sda_pin == g_cam_scl_pin)
728	    { syslog(LOG_ERR, "[camera] SDA=SCL=%d conflict\n", g_cam_sda_pin);
729	      ok = false; }
730	  if (g_cam_rst_pin != CAMERA_GPIO_UNCONFIGURED &&
731	      !gpio_is_valid(g_cam_rst_pin))
732	    { syslog(LOG_ERR, "[camera] RST pin %d out of range\n", g_cam_rst_pin);
733	      ok = false; }
734	  if (g_cam_pwr_pin != CAMERA_GPIO_UNCONFIGURED &&
735	      !gpio_is_valid(g_cam_pwr_pin))
736	    { syslog(LOG_ERR, "[camera] PWR pin %d out of range\n", g_cam_pwr_pin);
737	      ok = false; }
738	  if (g_cam_pwdn_pin != CAMERA_GPIO_UNCONFIGURED &&
739	      !gpio_is_valid(g_cam_pwdn_pin))
740	    { syslog(LOG_ERR, "[camera] PWDN pin %d out of range\n", g_cam_pwdn_pin);
741	      ok = false; }
742	  if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED &&
743	      !gpio_is_valid(g_cam_mclk_pin))
