857	int bk7258_camera_id(void)
858	{
859	  gpio_state_t sda_saved, scl_saved, rst_saved;
860	  gpio_state_t pwr_saved, pwdn_saved;
861	  mclk_state_t mclk_saved = { .valid = false };
862	  int id_h = -1, id_l = -1;
863	  uint16_t chip_id;
864	  int ret, stop_ret;
865	  bool sda_ok = false, scl_ok = false, rst_ok = false;
866	  bool pwr_ok = false, pwdn_ok = false;
867	  bool mclk_on = false;
868	
869	  /* ===== Config validation — NO MMIO before this ===== */
870	
871	  ret = camera_check_config();
872	  if (ret < 0) return ret;
873	
874	  syslog(LOG_INFO, "[camera] Config OK\n");
875	
876	  /* ===== GPIO setup ===== */
877	
878	  gpio_save_state(g_cam_sda_pin, &sda_saved); sda_ok = true;
879	  gpio_save_state(g_cam_scl_pin, &scl_saved); scl_ok = true;
880	
881	  gpio_release(g_cam_sda_pin);
882	  gpio_release(g_cam_scl_pin);
883	  up_udelay(100);
884	
885	  if (g_cam_rst_pin != CAMERA_GPIO_UNCONFIGURED)
886	    { gpio_save_state(g_cam_rst_pin, &rst_saved); rst_ok = true; }
887	
888	  camera_power_on(&pwr_saved, &pwr_ok, &pwdn_saved, &pwdn_ok);
889	
890	  if (g_cam_mclk_pin != CAMERA_GPIO_UNCONFIGURED)
891	    { mclk_save_state(&mclk_saved);
892	      mclk_enable_24mhz(); mclk_on = true;
893	      up_udelay(500); }
894	
895	  if (rst_ok) camera_reset();
896	
897	  /* ===== SCCB ID read ===== */
898	
899	  id_h = sccb_read_reg(GC2145_REG_ID_H);
900	  if (id_h < 0)
901	    { syslog(LOG_ERR, "[camera] ID high read fail: %d\n", id_h);
902	      ret = id_h; goto cleanup; }
903	
904	  id_l = sccb_read_reg(GC2145_REG_ID_L);
905	  if (id_l < 0)
906	    { syslog(LOG_ERR, "[camera] ID low read fail: %d\n", id_l);
907	      ret = id_l; goto cleanup; }
908	
909	  chip_id = (uint16_t)((id_h << 8) | id_l);
910	  syslog(LOG_INFO,
911	         "[camera] GC2145 ID: 0x%04X (0xF0=0x%02X 0xF1=0x%02X)\n",
912	         chip_id, (uint8_t)id_h, (uint8_t)id_l);
913	
914	  ret = (chip_id == 0x2145) ? 0 : -ENODEV;
915	
916	cleanup:
917	
918	  /* ===== Restore ALL saved GPIO states ===== */
919	
920	  stop_ret = sccb_stop();
921	
922	  if (mclk_on)     mclk_restore_state(&mclk_saved);
923	  if (rst_ok)      gpio_restore_state(&rst_saved);
924	  if (pwdn_ok)     gpio_restore_state(&pwdn_saved);
925	  if (pwr_ok)      gpio_restore_state(&pwr_saved);
926	  if (scl_ok)      gpio_restore_state(&scl_saved);
927	  if (sda_ok)      gpio_restore_state(&sda_saved);
928	
929	  syslog(LOG_INFO, "[camera] Cleanup done — pins restored\n");
930	
931	  if (ret == 0 && stop_ret < 0) ret = stop_ret;
932	
933	  return ret;
934	}
