617	
618	static void camera_reset(void)
619	{
620	#ifdef CONFIG_CAMERA_RST_ACTIVE_LOW
621	  gpio_drive_low(g_cam_rst_pin);
622	  up_udelay(10000);
623	  gpio_release(g_cam_rst_pin);
624	  up_udelay(5000);
625	#else
626	  gpio_set_output_high(g_cam_rst_pin);
627	  up_udelay(10000);
628	  gpio_drive_low(g_cam_rst_pin);
629	  up_udelay(5000);
630	#endif
631	}
