static int sccb_write_reg(uint8_t reg_addr, uint8_t val)
{
    int ret, stop_ret;

    ret = sccb_start();
    if (ret < 0) return ret;

    ret = sccb_write_byte((uint8_t)(GC2145_SCCB_ADDR << 1) | 0);  // write addr
    if (ret < 0) goto stop_fail;

    ret = sccb_write_byte(reg_addr);  // register address
    if (ret < 0) goto stop_fail;

    ret = sccb_write_byte(val);  // data value
    if (ret < 0) goto stop_fail;

    stop_ret = sccb_stop();
    if (stop_ret < 0) return stop_ret;

    return 0;

stop_fail:
    stop_ret = sccb_stop();
    return (stop_ret < 0) ? stop_ret : ret;
}
```

