static bool dvp_pins_configed = false;
static gpio_state_t g_dvp_state[11];  // P29-P39 = 11 pins

static int dvp_io_config(void)
{
    int i;
    uint32_t val;

    for (i = 0; i < 11; i++)
    {
        int pin = 29 + i;
        gpio_save_state(pin, &g_dvp_state[i]);

        // Set function select = 0 (JPEG/DVP function)
        val = getreg32(BK7258_SYS_GPIO_FUNC(pin));
        int shift = (pin & 7) * 4;
        val &= ~(0xFu << shift);  // clear function field
        val |= (0u << shift);     // set to 0        putreg32(val, BK7258_SYS_GPIO_FUNC(pin));

        // Set CFG: disable output, disable input, disable pull, enable second func
        val = getreg32(BK7258_GPIO_CFG(pin));
        val |=  GPIO_CFG_OUTPUT_EN;    // bit3=1: output DISABLED (active-low)
        val &= ~GPIO_CFG_INPUT_EN;     // bit2=0: input disabled
        val &= ~GPIO_CFG_PULL_EN;      // bit5=0: pull disabled
        val |=  GPIO_CFG_SECOND_FUNC;  // bit6=1: peripheral function
        putreg32(val, BK7258_GPIO_CFG(pin));
    }

    dvp_pins_configed = true;
    return 0;
}

static void dvp_io_deconfig(void)
{
    int i;
    if (!dvp_pins_configed) return;

    for (i = 10; i >= 0; i--)
    {
        gpio_restore_state(&g_dvp_state[i]);
    }
    dvp_pins_configed = false;
}
