    syslog(LOG_INFO, "[camera] 640x480 table written (%d entries)\n", (int)ARRAY_SIZE(gc2145_640x480));

    // Readback verify: check reg 0x84 = 0x06 (RGB565)
    {
        int val = sccb_read_reg(0x84);
        if (val < 0)
