    syslog(LOG_INFO, "[camera] MCLK/power left ON for oscilloscope verification\n");

    // Restore SCCB pins (MCLK/power stay on)
    stop_ret = sccb_stop();
    gpio_restore_state(&scl_saved);
    gpio_restore_state(&sda_saved);

    return 0;

cleanup:
