int bk7258_camera_buf(void)
{
    int ret, i;
    volatile uint8_t *buf;

    ret = camera_framebuf_alloc();
    if (ret < 0) return ret;

    // Write test pattern to buf[0]
    buf = g_camera_buf[0];
    for (i = 0; i < CAMERA_FRAME_SIZE; i++)
    {
        buf[i] = (uint8_t)(i & 0xFF);
    }

    // Readback verify: every1024 bytes + first/last256 bytes full check
    for (i = 0; i < CAMERA_FRAME_SIZE; i++)
    {
        bool check = false;

        // First256 bytes: full check
        if (i < 256) check = true;
        // Last256 bytes: full check
        else if (i >= CAMERA_FRAME_SIZE - 256) check = true;
        // Every1024 bytes: sampled check
        else if ((i & 1023) == 0) check = true;

        if (check && buf[i] != (uint8_t)(i & 0xFF))
        {
            syslog(LOG_ERR, "[camera] Framebuf[%d] mismatch: 0x%02X vs 0x%02X\n",
                   i, buf[i], (uint8_t)(i & 0xFF));
            return -EIO;
        }
    }

    syslog(LOG_INFO, "[camera] Framebuf verify OK (%d bytes, buf0=0x%08lX)\n",
           CAMERA_FRAME_SIZE, (unsigned long)g_camera_buf[0]);

    return 0;
}
