55	// DVP work thread function
56	static void dvp_work_thread(void *param)
57	{
58	    dvp_driver_handle_t *handle = (dvp_driver_handle_t *)param;
59	    dvp_event_msg_t msg;
60	    bk_err_t ret;
61	    LOGD("%s thread started\n", __func__);
62	
63	    rtos_set_semaphore(&handle->thread_sem);
64	
65	    while (!handle->thread_should_exit)
66	    {
67	        ret = rtos_pop_from_queue(&handle->dvp_msg_queue, &msg, BEKEN_WAIT_FOREVER);
68	        if (ret != BK_OK)
69	        {
70	            continue;
71	        }
72	
73	        // Process different types of events
74	        switch (msg.type)
75	        {
76	            case DVP_EVENT_YUV_EOF:
77	            {
78	                frame_buffer_t *yuv_frame = (frame_buffer_t *)msg.param1;
79	                uint8_t status = (uint8_t)msg.param2;
80	                if (yuv_frame && handle->callback && handle->callback->complete)
81	                {
82	                    handle->callback->complete(IMAGE_YUV, yuv_frame, status);
83	                }
84	                break;
85	            }
86	
87	            case DVP_EVENT_JPEG_EOF:
88	            {
89	                frame_buffer_t *jpeg_frame = (frame_buffer_t *)msg.param1;
90	                uint8_t status = (uint8_t)msg.param2;
91	                if (jpeg_frame && handle->callback && handle->callback->complete)
92	                {
93	                    handle->callback->complete(IMAGE_MJPEG, jpeg_frame, status);
94	                }
95	                break;
96	            }
97	
98	            case DVP_EVENT_H264_EOF:
99	            {
100	                frame_buffer_t *h264_frame = (frame_buffer_t *)msg.param1;
101	                uint8_t status = (uint8_t)msg.param2;
102	                if (h264_frame && handle->callback && handle->callback->complete)
103	                {
104	#ifdef CONFIG_H264_ADD_SELF_DEFINE_SEI
105	                    // Process H264 SEI in thread
106	                    h264_frame->crc = hnd_crc8(h264_frame->frame, h264_frame->length, 0xFF);
107	                    h264_frame->length += H264_SELF_DEFINE_SEI_SIZE;
108	                    os_memcpy(&handle->sei[23], (uint8_t *)h264_frame, sizeof(frame_buffer_t));
109	                    os_memcpy(&h264_frame->frame[h264_frame->length - H264_SELF_DEFINE_SEI_SIZE], &handle->sei[0], H264_SELF_DEFINE_SEI_SIZE);
110	#endif
111	                    handle->callback->complete(IMAGE_H264, h264_frame, status);
112	                }
113	                break;
114	            }
115	
116	            case DVP_EVENT_EXIT:
117	            {
118	                LOGD("Exiting DVP work thread\n");
119	                goto exit;
120	            }
121	
122	            default:
123	                LOGW("Unknown event type: %d\n", msg.type);
124	                break;
125	        }
126	    }
127	
128	exit:
129	    // Release thread exit semaphore to notify deinit that thread has fully exited
130	    if (handle->thread_sem != NULL)
131	    {
132	        rtos_set_semaphore(&handle->thread_sem);
133	    }
134	
135	    handle->thread_should_exit = true;
136	    LOGD("%s thread exited\n", __func__);
137	    
138	    rtos_delete_thread(NULL);
139	}
