1200	    bk_dvp_config_t *config = handle->config;
1201	    const dvp_sensor_config_t *sensor = handle->sensor;
1202	    yuv_buf_config_t yuv_mode_config = {0};
1203	
1204	    if (config->img_format == IMAGE_YUV)
1205	    {
1206	        yuv_mode_config.work_mode = YUV_MODE;
1207	    }
1208	    else if (config->img_format & IMAGE_MJPEG)
1209	    {
1210	        yuv_mode_config.work_mode = JPEG_MODE;
1211	    }
1212	    else if (config->img_format & IMAGE_H264)
1213	    {
1214	        yuv_mode_config.work_mode = H264_MODE;
1215	    }
1216	
1217	    yuv_mode_config.mclk_div = YUV_MCLK_DIV_3;
1218	
1219	    yuv_mode_config.x_pixel = config->width / 8;
1220	    yuv_mode_config.y_pixel = config->height / 8;
1221	    yuv_mode_config.yuv_mode_cfg.vsync = sensor->vsync;
1222	    yuv_mode_config.yuv_mode_cfg.hsync = sensor->hsync;
1223	
1224	    LOGD("%s, %d-%d, fmt:%X\r\n", __func__, config->width, config->height, config->img_format);
1225	
1226	    switch (sensor->fmt)
1227	    {
1228	        case PIXEL_FMT_YUYV:
1229	            yuv_mode_config.yuv_mode_cfg.yuv_format = YUV_FORMAT_YUYV;
1230	            break;
1231	
1232	        case PIXEL_FMT_UYVY:
1233	            yuv_mode_config.yuv_mode_cfg.yuv_format = YUV_FORMAT_UYVY;
1234	            break;
1235	
1236	        case PIXEL_FMT_YYUV:
1237	            yuv_mode_config.yuv_mode_cfg.yuv_format = YUV_FORMAT_YYUV;
1238	            break;
1239	
1240	        case PIXEL_FMT_UVYY:
1241	            yuv_mode_config.yuv_mode_cfg.yuv_format = YUV_FORMAT_UVYY;
1242	            break;
1243	
1244	        default:
1245	            LOGE("YUV_BUF MODULE not support this sensor input format\r\n");
1246	            ret = BK_ERR_PARAM;
1247	    }
1248	
1249	    if (ret != BK_OK)
1250	    {
1251	        return ret;
1252	    }
1253	
1254	    if (config->img_format & IMAGE_H264 || config->img_format & IMAGE_MJPEG)
1255	    {
1256	        if (handle->encode_buffer == NULL)
1257	        {
1258	            LOGE("encode buffer is NULL\r\n");
1259	            return BK_ERR_NO_MEM;
1260	        }
1261	
1262	        LOGD("%s, encode_buf:%p\r\n", __func__, handle->encode_buffer);
1263	
1264	        yuv_mode_config.base_addr = handle->encode_buffer;
1265	    }
1266	
1267	    ret = bk_yuv_buf_init(&yuv_mode_config);
1268	    if (ret != BK_OK)
1269	    {
1270	        LOGE("yuv_buf yuv mode init error\n");
1271	    }
1272	
1273	    return ret;
1274	}
