/****************************************************************************
 * Name: bk7258_camera_stream
 *
 * Description:
 *   Phase 1 Round 3 Step 5: continuous capture with ping-pong buffering.
 *
 *   Captures n_frames frames (default 30, range 1-1000) using two frame
 *   buffers in PSRAM.  The ISR toggles between buffers; the main loop
 *   polls for completed frames and computes statistics.
 *
 *   Prerequisites: camera init + camera buf.
 *
 *   On exit: interrupts detached, controller registers restored.
 *
 ****************************************************************************/

int bk7258_camera_stream(int n_frames)
{
  int ret;
  uint32_t prev_count;
  uint32_t t0_ms;
  uint32_t elapsed_ms;
  int captured;
  int timeout_ms;
  int i;

  /* Clamp arguments */

  if (n_frames <= 0)
    {
      n_frames = 30;
    }
  else if (n_frames > STREAM_BUF_MAX)
    {
      n_frames = STREAM_BUF_MAX;
    }

  /* Check prerequisites */

  if (!g_dvp_pins_configed)
    {
      syslog(LOG_ERR,
             "[camera] DVP pins not configured — run 'camera init' first\n");
      return -ENODEV;
    }

  if (!g_framebuf_allocated)
    {
      syslog(LOG_ERR,
             "[camera] Frame buffers not allocated — run 'camera buf' first\n");
      return -ENOMEM;
    }

  /* Configure DVP controller — output to buf[0] initially */

  ret = dvp_ctrl_config((uint32_t)(uintptr_t)g_camera_buf[0]);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[camera] DVP ctrl config failed: %d\n", ret);
      goto cleanup_ctrl;
    }

  /* Attach interrupt handler */

  ret = dvp_irq_attach();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[camera] DVP IRQ attach failed: %d\n", ret);
      goto cleanup_irq;
    }

  /* Reset streaming state */

  g_dvp_vsync_count = 0;
  g_dvp_frame_count = 0;
  g_pingpong_count  = 0;
  g_drop_count      = 0;
  g_cur_buf         = 0;
  g_ready_buf       = -1;
  g_stream_active   = true;

  syslog(LOG_INFO,
         "[camera] Stream start: capturing %d frames "
         "(buf[0]=0x%08lX buf[1]=0x%08lX)\n",
         n_frames,
         (unsigned long)(uintptr_t)g_camera_buf[0],
         (unsigned long)(uintptr_t)g_camera_buf[1]);

  /* Capture loop — poll for ready frames */

  captured = 0;
  prev_count = 0;
  t0_ms = 0;  /* elapsed time tracked by frame arrival */

  while (captured < n_frames)
    {
      /* Wait for a frame to become ready (timeout 5s) */

      timeout_ms = 5000;
      while (g_ready_buf < 0 && timeout_ms > 0)
        {
          up_udelay(1000);
          timeout_ms--;
        }

      if (g_ready_buf < 0)
        {
          syslog(LOG_ERR,
                 "[camera] TIMEOUT waiting for frame %d/%d "
                 "(VSYNC=%lu FRAME=%lu)\n",
                 captured + 1, n_frames,
                 (unsigned long)g_dvp_vsync_count,
                 (unsigned long)g_dvp_frame_count);
          ret = -ETIMEDOUT;
          break;
        }

      captured++;

      /* Compute Y component average of the ready frame (8x8 sampled) */

      {
        const uint8_t *buf = g_camera_buf[g_ready_buf];
        uint32_t y_sum = 0;
        int samples = 0;

        for (i = 0; i < CAMERA_FRAME_SIZE; i += 16 * CAMERA_HRES)
          {
            int j;
            for (j = 0; j < CAMERA_HRES; j += 16)
              {
                y_sum += buf[i + j];  /* Y is first byte in YUYV */
                samples++;
              }
          }

        if (captured == 1 || captured == n_frames || (captured % 10) == 0)
          {
            syslog(LOG_INFO,
                   "[camera] %d/%d  VSYNC=%lu  FRAME=%lu  "
                   "Y_avg=%lu  drop=%lu\n",
                   captured, n_frames,
                   (unsigned long)g_dvp_vsync_count,
                   (unsigned long)g_dvp_frame_count,
                   (unsigned long)(samples > 0 ? y_sum / samples : 0),
                   (unsigned long)g_drop_count);
          }
      }

      /* Mark frame consumed — ISR can now advance */

      g_ready_buf = -1;
    }

  /* Stop streaming */

  g_stream_active = false;

  /* Report statistics */

  elapsed_ms = g_dvp_frame_count > 0 ? (uint32_t)g_dvp_frame_count * 33 : 0;

  syslog(LOG_INFO,
         "[camera] Stream done: captured=%d  total=%lu  "
         "drop=%lu  vsync=%lu\n",
         captured,
         (unsigned long)g_pingpong_count,
         (unsigned long)g_drop_count,
         (unsigned long)g_dvp_vsync_count);

  if (elapsed_ms > 0)
    {
      syslog(LOG_INFO,
             "[camera] Elapsed: ~%lu ms  Avg FPS: ~%lu\n",
             (unsigned long)elapsed_ms,
             (unsigned long)(captured * 1000 / (elapsed_ms > 0 ? elapsed_ms : 1)));
    }

  ret = captured > 0 ? 0 : -EIO;

cleanup_irq:
  dvp_irq_detach();

cleanup_ctrl:
  dvp_ctrl_deconfig();

  return ret;
}

/****************************************************************************
 * Name: yuyv_to_rgb565_scaled
 *
 * Description:
 *   Convert a YUYV 640x480 frame to RGB565 160x160 with 4:1 horizontal
 *   and 3:1 vertical downscaling.  Writes to dst (must be >= 51200 bytes).
 *
 *   Integer-only conversion (no floating point):
 *     R = Y + 1.402*(V-128)  ≈ Y + (V-128) + (V-128)*51/128
 *     G = Y - 0.344*(U-128) - 0.714*(V-128)
 *       ≈ Y - (U-128)*28/81 - (V-128)*365/512
 *     B = Y + 1.772*(U-128)  ≈ Y + (U-128) + (U-128)*99/128
 *
 ****************************************************************************/

static void yuyv_to_rgb565_scaled(const uint8_t *src,
                                  uint8_t *dst,
                                  int src_w,
                                  int src_h,
                                  int dst_w,
                                  int dst_h)
{
  int sx;            /* source X (pixels) */
  int sy;            /* source Y (rows) */
  int dx;
  int dy;
  uint16_t *out = (uint16_t *)dst;

  int scale_x = src_w / dst_w;  /* 4 */
  int scale_y = src_h / dst_h;  /* 3 */

  for (dy = 0; dy < dst_h; dy++)
    {
      sy = dy * scale_y;
      const uint8_t *row = src + sy * src_w * 2;

      for (dx = 0; dx < dst_w; dx++)
        {
          uint8_t y0;
          int cb_i;
          int cr_i;
          int r;
          int g;
          int b;
          uint16_t rgb;

          sx = dx * scale_x;

          /* YUYV: [Y0 U0 Y1 V0] per 2 pixels.
           * Pixel sx: pair index = sx / 2, byte offset = pair * 4.
           * Y = byte 0 (even pixel) or byte 2 (odd pixel).
           * U = byte 1, V = byte 3.
           */

          int pair = sx / 2;
          const uint8_t *p = row + pair * 4;

          y0  = (sx & 1) ? p[2] : p[0];
          cb_i = (int)p[1] - 128;
          cr_i = (int)p[3] - 128;

          /* Integer-only YUV→RGB */

          r = (int)y0 + cr_i + (cr_i * 51 / 128);
          g = (int)y0 - (cb_i * 28 / 81) - (cr_i * 365 / 512);
          b = (int)y0 + cb_i + (cb_i * 99 / 128);

          /* Clamp */

          if (r < 0) r = 0; if (r > 255) r = 255;
          if (g < 0) g = 0; if (g > 255) g = 255;
          if (b < 0) b = 0; if (b > 255) b = 255;

          /* Pack RGB565 */

          rgb = (uint16_t)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
          out[dy * dst_w + dx] = rgb;
        }
    }
}

/****************************************************************************
 * Name: bk7258_camera_preview
 *
 * Description:
 *   Phase 1 Round 3 Step 6: capture + LCD preview.
 *
 *   Captures n_frames (default 100) frames.  Each captured frame is
 *   converted from YUYV 640x480 to RGB565 160x160 and blitted to the
 *   GC9D01 LCD via SPI.  Reports capture fps, display fps, drop count.
 *
 *   Prerequisites: camera init + camera buf + LCD initialized.
 *
 ****************************************************************************/

int bk7258_camera_preview(int n_frames)
{
  int ret;
  int captured;
  int timeout_ms;
  int i;
  uint32_t t_start;
  uint32_t t_end;
  uint32_t t_prev;
  uint32_t now;
  uint32_t cap_ms;
  uint32_t disp_ms;
  volatile uint8_t *preview_buf;

  /* Preview buffer in PSRAM (51200 bytes at 0x6012C000) */

  preview_buf = (volatile uint8_t *)PREVIEW_ADDR;

  /* Clamp arguments */

  if (n_frames <= 0)
    {
      n_frames = 100;
    }
  else if (n_frames > STREAM_BUF_MAX)
    {
      n_frames = STREAM_BUF_MAX;
    }

  /* Check prerequisites */

  if (!g_dvp_pins_configed)
    {
      syslog(LOG_ERR,
             "[camera] DVP pins not configured — run 'camera init' first\n");
      return -ENODEV;
    }

  if (!g_framebuf_allocated)
    {
      syslog(LOG_ERR,
             "[camera] Frame buffers not allocated — run 'camera buf' first\n");
      return -ENOMEM;
    }

  /* Configure DVP controller — output to buf[0] initially */

  ret = dvp_ctrl_config((uint32_t)(uintptr_t)g_camera_buf[0]);
  if (ret < 0)
    {
      syslog(LOG_ERR, "[camera] DVP ctrl config failed: %d\n", ret);
      goto cleanup_ctrl;
    }

  /* Attach interrupt handler */

  ret = dvp_irq_attach();
  if (ret < 0)
    {
      syslog(LOG_ERR, "[camera] DVP IRQ attach failed: %d\n", ret);
      goto cleanup_irq;
    }

  /* Reset streaming state */

  g_dvp_vsync_count = 0;
  g_dvp_frame_count = 0;
  g_pingpong_count  = 0;
  g_drop_count      = 0;
  g_cur_buf         = 0;
  g_ready_buf       = -1;
  g_stream_active   = true;

  syslog(LOG_INFO,
         "[camera] Preview start: %d frames to LCD (160x160)\n",
         n_frames);

  /* Warm-up — discard first 30 frames (sensor AE/AWB convergence) */

  for (i = 0; i < 30; i++)
    {
      timeout_ms = 1000;
      while (g_ready_buf < 0 && timeout_ms > 0)
        {
          up_udelay(1000);
          timeout_ms--;
        }

      if (g_ready_buf < 0)
        {
          syslog(LOG_ERR, "[camera] TIMEOUT during warm-up frame %d\n", i);
          ret = -ETIMEDOUT;
          goto stop_stream;
        }

      g_ready_buf = -1;  /* discard */
    }

  /* Preview loop */

  captured = 0;
  t_start = 0;
  t_prev  = 0;
  t_end   = 0;

  while (captured < n_frames)
    {
      /* Wait for a frame */

      timeout_ms = 5000;
      while (g_ready_buf < 0 && timeout_ms > 0)
        {
          up_udelay(1000);
          timeout_ms--;
        }

      if (g_ready_buf < 0)
        {
          syslog(LOG_ERR,
                 "[camera] TIMEOUT waiting for preview frame %d/%d\n",
                 captured + 1, n_frames);
          ret = -ETIMEDOUT;
          break;
        }

      /* Capture timestamp (approximate from frame count) */

      now = g_dvp_frame_count * 33;  /* ~30fps → 33ms per frame */
      if (captured == 0)
        {
          t_start = now;
          t_prev  = now;
        }

      /* Convert YUYV → RGB565 scaled 160x160 into preview buffer */

      yuyv_to_rgb565_scaled((const uint8_t *)g_camera_buf[g_ready_buf],
                            (uint8_t *)preview_buf,
                            CAMERA_HRES, CAMERA_VRES,
                            PREVIEW_W, PREVIEW_H);

      /* Blit to LCD */

      bk7258_lcd_blit_rgb565(0, 0, PREVIEW_W, PREVIEW_H,
                              (const uint8_t *)preview_buf);

      t_end = now;
      captured++;

      /* Mark consumed */

      g_ready_buf = -1;

