/****************************************************************************
 * Name: dvp_frame_get / dvp_frame_put
 *
 * Description:
 *   Frame consumer API — must be used as a pair.
 *
 *   dvp_frame_get():
 *     Enters critical section, atomically transfers g_ready_buf to
 *     g_busy_buf (claiming exclusive read access), returns the buffer
 *     address.  Returns NULL if no frame is ready.
 *
 *   dvp_frame_put():
 *     Enters critical section, clears g_busy_buf so the ISR knows
 *     the buffer is available for DMA again.
 *
 *   The critical section protects only pointer/index operations —
 *   no data copy or LCD I/O happens inside.
 *
 ****************************************************************************/

static uint32_t dvp_frame_get(void)
{
  irqstate_t flags;
  int idx;
  uint32_t addr;

  flags = enter_critical_section();
  idx = g_ready_buf;
  if (idx >= 0)
    {
      g_busy_buf  = idx;
      g_ready_buf = -1;
      addr = (uint32_t)(uintptr_t)g_camera_buf[idx];
    }
  else
    {
      addr = 0;
    }

  leave_critical_section(flags);
  return addr;
}

static void dvp_frame_put(void)
{
  irqstate_t flags;

  flags = enter_critical_section();
  g_busy_buf = -1;
  leave_critical_section(flags);
}

