/****************************************************************************
 * DVP Module Clock Enable / Disable
 *
 * Enables H264 clock (bit[0]) and YUV_BUF clock (bit[3]) at 0x44010034,
 * routes YUV_BUF interrupt (bit[26]) at 0x4401008C, and releases
 * soft reset + clock gate bypass at 0x48020008.
 ****************************************************************************/

static void dvp_module_clk_enable(void)
{
  uint32_t val;

  /* Enable H264 + YUV_BUF module clocks */

  val = getreg32(CAMERA_CLK_EN_REG);
  val |= (CAMERA_H264_CLKEN_BIT | CAMERA_YUV_BUF_CLKEN_BIT);
  putreg32(val, CAMERA_CLK_EN_REG);

  /* Route YUV_BUF interrupt to system interrupt controller */

  val = getreg32(CAMERA_SYS_INT_32_63_REG);
  val |= CAMERA_YUVB_INT_EN_BIT;
  putreg32(val, CAMERA_SYS_INT_32_63_REG);

  /* Soft reset release + clock gate bypass */

  val = getreg32(YUV_BUF_SOFT_RST_REG);
  val |= (YUV_BUF_SOFT_RST_BIT | YUV_BUF_CLK_GATE_BIT);
  putreg32(val, YUV_BUF_SOFT_RST_REG);

  up_udelay(100);
}

static void dvp_module_clk_disable(void)
{
  uint32_t val;

  /* Disable YUV_BUF interrupt routing */

  val = getreg32(CAMERA_SYS_INT_32_63_REG);
  val &= ~CAMERA_YUVB_INT_EN_BIT;
  putreg32(val, CAMERA_SYS_INT_32_63_REG);

  /* Disable H264 + YUV_BUF module clocks */

  val = getreg32(CAMERA_CLK_EN_REG);
  val &= ~(CAMERA_H264_CLKEN_BIT | CAMERA_YUV_BUF_CLKEN_BIT);
  putreg32(val, CAMERA_CLK_EN_REG);
}

/****************************************************************************
 * DVP Controller Register Save / Restore
 ****************************************************************************/

static void dvp_ctrl_save_state(void)
{
  g_dvp_ctrl_saved.ctrl       = getreg32(YUV_BUF_REG_0x04);
  g_dvp_ctrl_saved.pixel      = getreg32(YUV_BUF_REG_0x05);
  g_dvp_ctrl_saved.em_base    = getreg32(YUV_BUF_REG_0x08);
  g_dvp_ctrl_saved.int_en     = getreg32(YUV_BUF_REG_0x09);
  g_dvp_ctrl_saved.int_status = getreg32(YUV_BUF_REG_0x0a);
  g_dvp_ctrl_saved.valid      = true;
}

static void dvp_ctrl_restore_state(void)
{
  if (!g_dvp_ctrl_saved.valid) return;

  putreg32(g_dvp_ctrl_saved.int_en,     YUV_BUF_REG_0x09);
  putreg32(g_dvp_ctrl_saved.em_base,    YUV_BUF_REG_0x08);
  putreg32(g_dvp_ctrl_saved.pixel,      YUV_BUF_REG_0x05);
  putreg32(g_dvp_ctrl_saved.ctrl,       YUV_BUF_REG_0x04);

  g_dvp_ctrl_saved.valid = false;
}

/****************************************************************************
 * DVP Controller Config / Deconfig
 ****************************************************************************/

static int dvp_ctrl_config(uint32_t em_base_addr)
{
  uint32_t val;

  if (g_dvp_ctrl_configed) return 0;

  /* Save current register state */

  dvp_ctrl_save_state();

  /* Enable module clocks + system interrupt */

  dvp_module_clk_enable();

  /* Configure PIXEL register: frame_blk for 640x480 YUV */

  putreg32(CAMERA_FRAME_BLK, YUV_BUF_REG_0x05);

  /* Configure CTRL: YUYV format + YUV mode start */

  val = YUV_BUF_CTRL_FMT_YUYV | YUV_BUF_CTRL_YUV_MODE;
  putreg32(val, YUV_BUF_REG_0x04);

  /* Set DMA base address */

  putreg32(em_base_addr, YUV_BUF_REG_0x08);

  /* Enable VSYNC + YUV_ARRIVED interrupts */

  putreg32(YUV_BUF_INT_VSYNC_NEGE | YUV_BUF_INT_YUV_ARV,
           YUV_BUF_REG_0x09);

  /* Clear any pending interrupts */

  putreg32(YUV_BUF_INT_STATUS_MASK, YUV_BUF_REG_0x0a);

  g_dvp_ctrl_configed = true;
  return 0;
}

static void dvp_ctrl_deconfig(void)
{
  if (!g_dvp_ctrl_configed) return;

  /* Restore saved register state */

  dvp_ctrl_restore_state();

  /* Disable module clocks */

  dvp_module_clk_disable();

  g_dvp_ctrl_configed = false;
}

/****************************************************************************
 * DVP Interrupt Handler
 ****************************************************************************/

static int dvp_irq_handler(int irq, void *context, void *arg)
{
  uint32_t status;

  /* Read interrupt status */

  status = getreg32(YUV_BUF_REG_0x0a);

  /* VSYNC falling edge — frame start */

  if (status & YUV_BUF_INT_VSYNC_NEGE)
    {
      g_dvp_vsync_count++;
    }

  /* YUV arrived — frame data written to memory */

  if (status & YUV_BUF_INT_YUV_ARV)
    {
      g_dvp_frame_count++;

      /* Ping-pong: if streaming, advance to next buffer */

      if (g_stream_active)
        {
          int next_buf = 1 - g_cur_buf;

          if (g_ready_buf < 0 && next_buf != g_busy_buf)
            {
              /* Safe to advance: consumer took previous frame AND
               * the next buffer is not being read.
               */

              g_ready_buf = g_cur_buf;
              g_cur_buf = next_buf;
              g_pingpong_count++;
              putreg32((uint32_t)(uintptr_t)g_camera_buf[g_cur_buf],
                       YUV_BUF_REG_0x08);
            }
          else
            {
              /* Cannot advance: either previous frame not consumed
               * or next buffer is busy — drop this frame, keep
               * writing to current buffer.
               */

              g_drop_count++;
            }
        }
    }

  /* Clear all pending interrupts by writing 1s */

  putreg32(status & YUV_BUF_INT_STATUS_MASK, YUV_BUF_REG_0x0a);

  return OK;
}

static int dvp_irq_attach(void)
{
  int ret;

  if (g_dvp_irq_attached) return 0;

  ret = irq_attach(BK7258_IRQ_YUV_BUF, dvp_irq_handler, NULL);
  if (ret < 0) return ret;

  up_enable_irq(BK7258_IRQ_YUV_BUF);
  g_dvp_irq_attached = true;
  return 0;
}

static void dvp_irq_detach(void)
{
  if (!g_dvp_irq_attached) return;

  up_disable_irq(BK7258_IRQ_YUV_BUF);
  irq_detach(BK7258_IRQ_YUV_BUF);
  g_dvp_irq_attached = false;
}

/****************************************************************************
 * Frame Consumer API (critical-section protected)
 ****************************************************************************/

static uint32_t dvp_frame_get(void)
{
  irqstate_t flags;
  int idx;
  uint32_t addr;

  flags = enter_critical_section();
  idx = g_ready_buf;
  if (idx >= 0)
    {
      g_busy_buf  = idx;
      g_ready_buf = -1;
      addr = (uint32_t)(uintptr_t)g_camera_buf[idx];
    }
  else
    {
      addr = 0;
    }

  leave_critical_section(flags);
  return addr;
}

static void dvp_frame_put(void)
{
  irqstate_t flags;

  flags = enter_critical_section();
  g_busy_buf = -1;
  leave_critical_section(flags);
}

